import XCTest
import FreeSongCore
@testable import FreeSongStorage

final class JSONMetadataCacheTests: XCTestCase {

    private var cacheFile: URL!
    private var cache: JSONMetadataCache!

    override func setUp() {
        cacheFile = FileManager.default.temporaryDirectory
            .appendingPathComponent("freesong-metadata-test-\(UUID().uuidString)", isDirectory: true)
            .appendingPathComponent("metadata.json")
        cache = JSONMetadataCache(cacheFile: cacheFile)
    }

    override func tearDown() {
        try? FileManager.default.removeItem(at: cacheFile.deletingLastPathComponent())
        cache = nil
    }

    /// A burst of writes (e.g. parsing a whole library on first launch) should
    /// coalesce into a single debounced disk write, not one write per call.
    func testBurstOfWritesCoalescesIntoOneDiskWrite() async throws {
        for index in 0..<20 {
            await cache.cacheMetadata(for: URL(fileURLWithPath: "/tmp/song\(index).onsong"), title: "Song \(index)", artist: nil)
        }

        // Nothing written yet - still debouncing.
        XCTAssertFalse(FileManager.default.fileExists(atPath: cacheFile.path))

        try await Task.sleep(nanoseconds: 150_000_000)

        XCTAssertTrue(FileManager.default.fileExists(atPath: cacheFile.path))
        let data = try Data(contentsOf: cacheFile)
        let decoded = try JSONDecoder().decode([String: JSONValue].self, from: data)
        XCTAssertEqual(decoded.count, 20)
    }

    func testCachedMetadataSurvivesReloadFromDisk() async throws {
        let file = URL(fileURLWithPath: "/tmp/reload.onsong")
        await cache.cacheMetadata(for: file, title: "Reload Title", artist: "Reload Artist")
        try await Task.sleep(nanoseconds: 150_000_000)

        let reloaded = JSONMetadataCache(cacheFile: cacheFile)
        let size = await reloaded.cacheSize
        XCTAssertEqual(size, 1)
    }
}

/// Minimal helper to decode the JSON cache file's values without depending on
/// JSONMetadataCache's private entry type.
private struct JSONValue: Decodable {}

import XCTest
@testable import FreeSongSync

final class CodebergAPIClientTests: XCTestCase {

    private var mockHTTP: MockHTTPClient!
    private var client: CodebergAPIClient!

    override func setUp() async throws {
        mockHTTP = MockHTTPClient()
        let config = CodebergConfiguration(owner: "test", repo: "test-repo")
        client = CodebergAPIClient(configuration: config, httpClient: mockHTTP)

        // Store a test token
        try KeychainStorage.store(token: "[REDACTED]")
    }

    override func tearDown() {
        try? KeychainStorage.delete()
        mockHTTP = nil
        client = nil
    }

    // MARK: - listDirectory

    func testListDirectory_returnsFiles() async throws {
        let sha = "abc123"
        mockHTTP.when("/contents/songs", data: SyncFixtures.directoryListing(files: [("song.onsong", sha)]))

        let items = try await client.listDirectory(path: "songs")

        XCTAssertEqual(items.count, 1)
        XCTAssertEqual(items.first?.name, "song.onsong")
        XCTAssertEqual(items.first?.sha, sha)
    }

    func testListDirectory_404returnsEmpty() async throws {
        mockHTTP.when("/contents/songs", data: Data(), statusCode: 404)

        let items = try await client.listDirectory(path: "songs")

        XCTAssertTrue(items.isEmpty)
    }

    func testListDirectory_401throws() async throws {
        mockHTTP.when("/contents/songs", data: SyncFixtures.errorResponse(message: "bad creds"), statusCode: 401)

        do {
            _ = try await client.listDirectory(path: "songs")
            XCTFail("Expected authenticationFailed error")
        } catch let error as SyncError {
            if case .authenticationFailed = error {
                // expected
            } else {
                XCTFail("Unexpected error: \(error)")
            }
        } catch {
            XCTFail("Unexpected error type: \(error)")
        }
    }

    // MARK: - getFileContent

    func testGetFileContent_returnsContent() async throws {
        let sha = "file_sha_456"
        let content = "Hello World"
        mockHTTP.when("/contents/songs/test.onsong", data: SyncFixtures.fileContent(sha: sha, content: content))

        let (data, returnedSHA) = try await client.getFileContent(path: "songs/test.onsong")

        XCTAssertEqual(returnedSHA, sha)
        XCTAssertEqual(String(data: data, encoding: .utf8), content)
    }

    func testGetFileContent_404throws() async throws {
        mockHTTP.when("/contents/songs/missing.onsong", data: Data(), statusCode: 404)

        do {
            _ = try await client.getFileContent(path: "songs/missing.onsong")
            XCTFail("Expected notFound error")
        } catch let error as SyncError {
            if case .notFound = error {
                // expected
            } else {
                XCTFail("Unexpected error: \(error)")
            }
        } catch {
            XCTFail("Unexpected error type: \(error)")
        }
    }

    // MARK: - createOrUpdateFile

    func testCreateOrUpdateFile_newFileSucceeds() async throws {
        let sha = "new_sha_789"
        mockHTTP.when("/contents/songs/new.onsong",
                       data: SyncFixtures.createUpdateResponse(sha: sha),
                       statusCode: 201)

        let response = try await client.createOrUpdateFile(
            path: "songs/new.onsong",
            content: Data("test".utf8),
            sha: nil
        )

        XCTAssertEqual(response.content?.sha, sha)
        XCTAssertEqual(response.commit.sha, "commit123")
    }

    func testCreateOrUpdateFile_updateSucceeds() async throws {
        let sha = "updated_sha"
        mockHTTP.when("/contents/songs/existing.onsong",
                       data: SyncFixtures.createUpdateResponse(sha: sha),
                       statusCode: 200)

        let response = try await client.createOrUpdateFile(
            path: "songs/existing.onsong",
            content: Data("updated".utf8),
            sha: "old_sha"
        )

        XCTAssertEqual(response.content?.sha, sha)
    }

    func testCreateOrUpdateFile_conflictThrows() async throws {
        mockHTTP.when("/contents/songs/stale.onsong",
                       data: SyncFixtures.errorResponse(message: "conflict"),
                       statusCode: 409)

        do {
            _ = try await client.createOrUpdateFile(
                path: "songs/stale.onsong",
                content: Data("data".utf8),
                sha: "stale_sha"
            )
            XCTFail("Expected conflict error")
        } catch let error as SyncError {
            if case .conflict = error {
                // expected
            } else {
                XCTFail("Unexpected error: \(error)")
            }
        } catch {
            XCTFail("Unexpected error type: \(error)")
        }
    }

    // MARK: - validateAccess

    func testValidateAccess_withValidToken_returnsTrue() async throws {
        mockHTTP.when("/user", data: SyncFixtures.userResponse, statusCode: 200)

        let valid = try await client.validateAccess()

        XCTAssertTrue(valid)
    }

    func testValidateAccess_withInvalidToken_returnsFalse() async throws {
        mockHTTP.when("/user", data: SyncFixtures.errorResponse(message: "Unauthorized"), statusCode: 401)

        let valid = try await client.validateAccess()

        XCTAssertFalse(valid)
    }

    // MARK: - Auth header

    func testRequest_includesTokenHeader() async throws {
        mockHTTP.when("/user", data: SyncFixtures.userResponse, statusCode: 200)

        _ = try await client.validateAccess()

        XCTAssertEqual(mockHTTP.requests.count, 1)
        let authHeader = mockHTTP.requests.first?.value(forHTTPHeaderField: "Authorization")
        XCTAssertEqual(authHeader, "token test_token_abc123")
    }

    func testRequest_withoutToken_throwsNotAuthenticated() async throws {
        try KeychainStorage.delete()
        mockHTTP.when("/user", data: Data(), statusCode: 200)

        do {
            _ = try await client.validateAccess()
            XCTFail("Expected notAuthenticated error")
        } catch let error as SyncError {
            if case .notAuthenticated = error {
                // expected
            } else {
                XCTFail("Unexpected error: \(error)")
            }
        } catch {
            XCTFail("Unexpected error type: \(error)")
        }
    }
}

import XCTest
@testable import FreeSongCore

final class ModelTests: XCTestCase {

    // MARK: - ChordPosition

    func testChordPositionInit() {
        let chord = ChordPosition(chord: "G", position: 5)
        XCTAssertEqual(chord.chord, "G")
        XCTAssertEqual(chord.position, 5)
    }

    func testChordPositionEquality() {
        let chord1 = ChordPosition(chord: "G", position: 5)
        let chord2 = ChordPosition(chord: "G", position: 5)
        let chord3 = ChordPosition(chord: "C", position: 5)
        XCTAssertEqual(chord1, chord2)
        XCTAssertNotEqual(chord1, chord3)
    }

    func testChordPositionCodable() throws {
        let chord = ChordPosition(chord: "G#m7", position: 10)
        let encoded = try JSONEncoder().encode(chord)
        let decoded = try JSONDecoder().decode(ChordPosition.self, from: encoded)
        XCTAssertEqual(chord, decoded)
    }

    // MARK: - KeyChange

    func testKeyChangeInit() {
        let keyChange = KeyChange(newKey: "D")
        XCTAssertEqual(keyChange.newKey, "D")
    }

    func testKeyChangeEquality() {
        let kc1 = KeyChange(newKey: "D")
        let kc2 = KeyChange(newKey: "D")
        let kc3 = KeyChange(newKey: "E")
        XCTAssertEqual(kc1, kc2)
        XCTAssertNotEqual(kc1, kc3)
    }

    func testKeyChangeCodable() throws {
        let keyChange = KeyChange(newKey: "F#m")
        let encoded = try JSONEncoder().encode(keyChange)
        let decoded = try JSONDecoder().decode(KeyChange.self, from: encoded)
        XCTAssertEqual(keyChange, decoded)
    }

    // MARK: - SongLine

    func testSongLineInit() {
        let line = SongLine(lyrics: "Amazing grace", chords: [ChordPosition(chord: "G", position: 0)])
        XCTAssertEqual(line.lyrics, "Amazing grace")
        XCTAssertEqual(line.chords.count, 1)
        XCTAssertNil(line.keyChange)
    }

    func testSongLineWithKeyChange() {
        let line = SongLine(lyrics: "", chords: [], keyChange: KeyChange(newKey: "D"))
        XCTAssertTrue(line.isKeyChange)
        XCTAssertEqual(line.keyChange?.newKey, "D")
    }

    func testSongLineAddChord() {
        var line = SongLine(lyrics: "Test")
        line.addChord(ChordPosition(chord: "C", position: 0))
        line.addChord(ChordPosition(chord: "F", position: 5))
        XCTAssertEqual(line.chords.count, 2)
    }

    func testSongLineEquality() {
        let line1 = SongLine(lyrics: "Test", chords: [ChordPosition(chord: "C", position: 0)])
        let line2 = SongLine(lyrics: "Test", chords: [ChordPosition(chord: "C", position: 0)])
        let line3 = SongLine(lyrics: "Different", chords: [ChordPosition(chord: "C", position: 0)])
        XCTAssertEqual(line1, line2)
        XCTAssertNotEqual(line1, line3)
    }

    func testSongLineCodable() throws {
        let line = SongLine(
            lyrics: "Amazing grace",
            chords: [ChordPosition(chord: "G", position: 0), ChordPosition(chord: "D", position: 7)],
            keyChange: KeyChange(newKey: "D")
        )
        let encoded = try JSONEncoder().encode(line)
        let decoded = try JSONDecoder().decode(SongLine.self, from: encoded)
        XCTAssertEqual(line, decoded)
    }

    // MARK: - SongSection

    func testSongSectionInit() {
        let section = SongSection(label: "Verse 1", lines: [])
        XCTAssertEqual(section.label, "Verse 1")
        XCTAssertTrue(section.lines.isEmpty)
    }

    func testSongSectionAddLine() {
        var section = SongSection(label: "Verse")
        let line = SongLine(lyrics: "Test line")
        section.addLine(line)
        XCTAssertEqual(section.lines.count, 1)
    }

    func testSongSectionEquality() {
        let section1 = SongSection(label: "Verse", lines: [SongLine(lyrics: "Test")])
        let section2 = SongSection(label: "Verse", lines: [SongLine(lyrics: "Test")])
        let section3 = SongSection(label: "Chorus", lines: [SongLine(lyrics: "Test")])
        XCTAssertEqual(section1, section2)
        XCTAssertNotEqual(section1, section3)
    }

    func testSongSectionCodable() throws {
        let section = SongSection(
            label: "Verse 1",
            lines: [
                SongLine(lyrics: "Line 1", chords: [ChordPosition(chord: "C", position: 0)]),
                SongLine(lyrics: "Line 2", chords: [ChordPosition(chord: "F", position: 0)])
            ]
        )
        let encoded = try JSONEncoder().encode(section)
        let decoded = try JSONDecoder().decode(SongSection.self, from: encoded)
        XCTAssertEqual(section, decoded)
    }

    // MARK: - Song

    func testSongInit() {
        let song = Song(title: "Test", artist: "Artist", key: "C")
        XCTAssertEqual(song.title, "Test")
        XCTAssertEqual(song.artist, "Artist")
        XCTAssertEqual(song.key, "C")
        XCTAssertTrue(song.sections.isEmpty)
    }

    func testSongDefaultValues() {
        let song = Song(title: "Test")
        XCTAssertEqual(song.transpose, 0)
        XCTAssertFalse(song.useFlats)
        XCTAssertFalse(song.useNashville)
    }

    func testSongAllChords() {
        let song = Song(
            title: "Test",
            sections: [
                SongSection(label: "V1", lines: [
                    SongLine(lyrics: "L1", chords: [ChordPosition(chord: "C", position: 0), ChordPosition(chord: "F", position: 5)]),
                    SongLine(lyrics: "L2", chords: [ChordPosition(chord: "G", position: 0)])
                ]),
                SongSection(label: "C", lines: [
                    SongLine(lyrics: "L3", chords: [ChordPosition(chord: "Am", position: 0)])
                ])
            ]
        )
        let chords = song.allChords
        XCTAssertEqual(chords.count, 4)
        XCTAssertTrue(chords.contains("C"))
        XCTAssertTrue(chords.contains("F"))
        XCTAssertTrue(chords.contains("G"))
        XCTAssertTrue(chords.contains("Am"))
    }

    func testSongHasChords() {
        let songWithChords = Song(title: "Test", sections: [SongSection(label: "V", lines: [SongLine(lyrics: "L", chords: [ChordPosition(chord: "C", position: 0)])])])
        let songWithoutChords = Song(title: "Test", sections: [SongSection(label: "V", lines: [SongLine(lyrics: "L")])])
        XCTAssertTrue(songWithChords.hasChords)
        XCTAssertFalse(songWithoutChords.hasChords)
    }

    func testSongEquality() {
        let song1 = Song(title: "Test", artist: "A", key: "C")
        let song2 = Song(title: "Test", artist: "A", key: "C")
        let song3 = Song(title: "Different", artist: "A", key: "C")
        XCTAssertEqual(song1, song2)
        XCTAssertNotEqual(song1, song3)
    }

    func testSongCodable() throws {
        let song = Song(
            title: "Test Song",
            artist: "Test Artist",
            key: "G",
            tempo: "120",
            timeSignature: "4/4",
            ccli: "123456",
            copyright: "© 2024",
            notes: "Some notes",
            sections: [
                SongSection(label: "Verse 1", lines: [
                    SongLine(lyrics: "Amazing grace", chords: [ChordPosition(chord: "G", position: 0), ChordPosition(chord: "D", position: 7)])
                ])
            ],
            originalKey: "G",
            transpose: 2,
            useFlats: true,
            useNashville: false
        )
        let encoded = try JSONEncoder().encode(song)
        let decoded = try JSONDecoder().decode(Song.self, from: encoded)
        XCTAssertEqual(song, decoded)
    }

    // MARK: - SetListItem

    func testSetListItemInit() {
        let item = SetListItem(songPath: "/path/song.txt", songTitle: "Song", songArtist: "Artist")
        XCTAssertEqual(item.songPath, "/path/song.txt")
        XCTAssertEqual(item.songTitle, "Song")
        XCTAssertEqual(item.songArtist, "Artist")
        XCTAssertEqual(item.position, 0)
        XCTAssertNil(item.notes)
        XCTAssertNotNil(item.id)
    }

    func testSetListItemWithAllFields() {
        let id = UUID()
        let setListId = UUID()
        let item = SetListItem(
            id: id,
            setListId: setListId,
            songPath: "/path/song.txt",
            songTitle: "Song",
            songArtist: "Artist",
            position: 5,
            notes: "Play slowly"
        )
        XCTAssertEqual(item.id, id)
        XCTAssertEqual(item.setListId, setListId)
        XCTAssertEqual(item.position, 5)
        XCTAssertEqual(item.notes, "Play slowly")
    }

    func testSetListItemEquality() {
        let item1 = SetListItem(songPath: "/path/song.txt", songTitle: "Song", songArtist: "Artist")
        let item2 = SetListItem(songPath: "/path/song.txt", songTitle: "Song", songArtist: "Artist")
        // Different UUIDs mean not equal
        XCTAssertNotEqual(item1, item2)

        // Same UUID
        let id = UUID()
        let item3 = SetListItem(id: id, songPath: "/path/song.txt", songTitle: "Song", songArtist: "Artist")
        let item4 = SetListItem(id: id, songPath: "/path/song.txt", songTitle: "Song", songArtist: "Artist")
        XCTAssertEqual(item3, item4)
    }

    func testSetListItemCodable() throws {
        let item = SetListItem(
            songPath: "/path/song.txt",
            songTitle: "Song Title",
            songArtist: "Artist Name",
            position: 3,
            notes: "Solo verse"
        )
        let encoded = try JSONEncoder().encode(item)
        let decoded = try JSONDecoder().decode(SetListItem.self, from: encoded)
        XCTAssertEqual(item.songPath, decoded.songPath)
        XCTAssertEqual(item.songTitle, decoded.songTitle)
        XCTAssertEqual(item.songArtist, decoded.songArtist)
        XCTAssertEqual(item.position, decoded.position)
        XCTAssertEqual(item.notes, decoded.notes)
    }

    // MARK: - SetList

    func testSetListInit() {
        let setlist = SetList(name: "Worship Set")
        XCTAssertEqual(setlist.name, "Worship Set")
        XCTAssertTrue(setlist.items.isEmpty)
        XCTAssertNotNil(setlist.id)
        XCTAssertEqual(setlist.createdAt, setlist.modifiedAt)
    }

    func testSetListAddItem() {
        var setlist = SetList(name: "Test")
        let item = SetListItem(songPath: "/path/song.txt", songTitle: "Song", songArtist: "Artist")
        setlist.addItem(item)

        XCTAssertEqual(setlist.items.count, 1)
        XCTAssertEqual(setlist.items[0].songTitle, "Song")
        XCTAssertEqual(setlist.items[0].setListId, setlist.id)
        XCTAssertEqual(setlist.items[0].position, 0)
        XCTAssertTrue(setlist.modifiedAt > setlist.createdAt)
    }

    func testSetListAddMultipleItems() {
        var setlist = SetList(name: "Test")
        setlist.addItem(SetListItem(songPath: "/1.txt", songTitle: "Song 1"))
        setlist.addItem(SetListItem(songPath: "/2.txt", songTitle: "Song 2"))
        setlist.addItem(SetListItem(songPath: "/3.txt", songTitle: "Song 3"))

        XCTAssertEqual(setlist.items.count, 3)
        XCTAssertEqual(setlist.items[0].position, 0)
        XCTAssertEqual(setlist.items[1].position, 1)
        XCTAssertEqual(setlist.items[2].position, 2)
    }

    func testSetListRemoveItem() {
        var setlist = SetList(name: "Test")
        setlist.addItem(SetListItem(songPath: "/1.txt", songTitle: "Song 1"))
        setlist.addItem(SetListItem(songPath: "/2.txt", songTitle: "Song 2"))
        setlist.addItem(SetListItem(songPath: "/3.txt", songTitle: "Song 3"))

        setlist.removeItem(at: 1)

        XCTAssertEqual(setlist.items.count, 2)
        XCTAssertEqual(setlist.items[0].songTitle, "Song 1")
        XCTAssertEqual(setlist.items[1].songTitle, "Song 3")
        XCTAssertEqual(setlist.items[0].position, 0)
        XCTAssertEqual(setlist.items[1].position, 1)
    }

    func testSetListMoveItem() {
        var setlist = SetList(name: "Test")
        setlist.addItem(SetListItem(songPath: "/1.txt", songTitle: "Song 1"))
        setlist.addItem(SetListItem(songPath: "/2.txt", songTitle: "Song 2"))
        setlist.addItem(SetListItem(songPath: "/3.txt", songTitle: "Song 3"))

        setlist.moveItem(from: 0, to: 2)

        XCTAssertEqual(setlist.items[0].songTitle, "Song 2")
        XCTAssertEqual(setlist.items[1].songTitle, "Song 3")
        XCTAssertEqual(setlist.items[2].songTitle, "Song 1")
        XCTAssertEqual(setlist.items[0].position, 0)
        XCTAssertEqual(setlist.items[1].position, 1)
        XCTAssertEqual(setlist.items[2].position, 2)
    }

    func testSetListUpdateName() {
        var setlist = SetList(name: "Original")
        let originalModified = setlist.modifiedAt

        // Small delay to ensure timestamp changes
        Thread.sleep(forTimeInterval: 0.01)
        setlist.updateName("Updated")

        XCTAssertEqual(setlist.name, "Updated")
        XCTAssertTrue(setlist.modifiedAt > originalModified)
    }

    func testSetListEquality() {
        let id = UUID()
        let date = Date()
        let setlist1 = SetList(id: id, name: "Test", createdAt: date, modifiedAt: date, items: [])
        let setlist2 = SetList(id: id, name: "Test", createdAt: date, modifiedAt: date, items: [])
        XCTAssertEqual(setlist1, setlist2)
    }

    func testSetListCodable() throws {
        var setlist = SetList(name: "Worship Set")
        setlist.addItem(SetListItem(songPath: "/song1.txt", songTitle: "Song 1", songArtist: "Artist 1"))
        setlist.addItem(SetListItem(songPath: "/song2.txt", songTitle: "Song 2", songArtist: "Artist 2"))

        let encoded = try JSONEncoder().encode(setlist)
        let decoded = try JSONDecoder().decode(SetList.self, from: encoded)

        XCTAssertEqual(setlist.name, decoded.name)
        XCTAssertEqual(setlist.items.count, decoded.items.count)
        XCTAssertEqual(setlist.items[0].songTitle, decoded.items[0].songTitle)
        XCTAssertEqual(setlist.items[1].songTitle, decoded.items[1].songTitle)
    }

    // MARK: - Sendable Conformance

    func testModelsAreSendable() {
        // This test compiles only if all models conform to Sendable
        let _: any Sendable = ChordPosition(chord: "C", position: 0)
        let _: any Sendable = KeyChange(newKey: "D")
        let _: any Sendable = SongLine(lyrics: "Test")
        let _: any Sendable = SongSection(label: "Verse")
        let _: any Sendable = Song(title: "Test")
        let _: any Sendable = SetListItem(songPath: "/path", songTitle: "Song")
        let _: any Sendable = SetList(name: "Set")
    }
}

import XCTest
@testable import FreeSongImport
@testable import FreeSongStorage

final class FreeSongImportAPITests: XCTestCase {

    var tmpDir: URL!
    var libraryRoot: URL!
    var fileRepo: FileSongRepository!
    var importer: FreeSongImport!

    override func setUp() async throws {
        try await super.setUp()
        tmpDir = try createTempDirectory()
        libraryRoot = tmpDir.appendingPathComponent("FreeSong", isDirectory: true)
        fileRepo = FileSongRepository(libraryRoot: libraryRoot)
        importer = FreeSongImport(
            fileRepository: fileRepo,
            setlistRepository: NullSetlistRepository()
        )
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tmpDir)
        try await super.tearDown()
    }

    // MARK: - Validation

    func testValidateBackupValidFile() throws {
        let dbURL = tmpDir.appendingPathComponent("OnSong.sqlite3")
        try createOnSongTestDatabase(at: dbURL)

        let zipURL = tmpDir.appendingPathComponent("backup.zip")
        try createTestZip(at: zipURL, files: [
            ("OnSong.sqlite3", try Data(contentsOf: dbURL)),
            ("song.onsong", makeOnSongContent(title: "Test", body: "[C]Lyrics")),
        ])

        let validation = importer.validateBackup(at: zipURL)

        XCTAssertTrue(validation.isValid)
        XCTAssertTrue(validation.hasDatabase)
        XCTAssertGreaterThan(validation.songFileCount, 0)
        XCTAssertGreaterThan(validation.totalEntries, 0)
        XCTAssertTrue(validation.warnings.isEmpty)
    }

    func testValidateBackupInvalidFile() {
        let txtURL = tmpDir.appendingPathComponent("notes.txt")
        try? Data("not a zip".utf8).write(to: txtURL)

        let validation = importer.validateBackup(at: txtURL)

        XCTAssertFalse(validation.isValid)
        XCTAssertFalse(validation.hasDatabase)
        XCTAssertEqual(validation.songFileCount, 0)
        XCTAssertFalse(validation.warnings.isEmpty)
    }

    func testValidateBackupMissingFile() {
        let missingURL = tmpDir.appendingPathComponent("does_not_exist.zip")

        let validation = importer.validateBackup(at: missingURL)

        XCTAssertFalse(validation.isValid)
        XCTAssertEqual(validation.totalEntries, 0)
        XCTAssertFalse(validation.warnings.isEmpty)
    }

    func testValidateBackupNoDatabase() throws {
        let zipURL = tmpDir.appendingPathComponent("songs-only.zip")
        try createTestZip(at: zipURL, files: [
            ("song1.onsong", makeOnSongContent(title: "Song 1", body: "[C]One")),
            ("song2.onsong", makeOnSongContent(title: "Song 2", body: "[G]Two")),
        ])

        let validation = importer.validateBackup(at: zipURL)

        XCTAssertTrue(validation.isValid, "Song files without DB should still be valid")
        XCTAssertFalse(validation.hasDatabase)
        XCTAssertEqual(validation.songFileCount, 2)
    }

    func testValidateBackupEmptyArchive() throws {
        let zipURL = tmpDir.appendingPathComponent("empty.zip")
        var eocd = Data([0x50, 0x4B, 0x05, 0x06])
        eocd.append(Data(repeating: 0x00, count: 18))
        try eocd.write(to: zipURL)

        let validation = importer.validateBackup(at: zipURL)

        XCTAssertFalse(validation.isValid, "Empty archive should not be valid")
        XCTAssertEqual(validation.totalEntries, 0)
        XCTAssertFalse(validation.warnings.isEmpty)
    }

    // MARK: - Import with Progress

    func testImportBackupFiresProgressCallbacks() async throws {
        let dbURL = tmpDir.appendingPathComponent("OnSong.sqlite3")
        try createOnSongTestDatabase(at: dbURL)

        let zipURL = tmpDir.appendingPathComponent("backup.zip")
        try createTestZip(at: zipURL, files: [
            ("OnSong.sqlite3", try Data(contentsOf: dbURL)),
            ("loose.onsong", makeOnSongContent(title: "Loose Song", body: "[C]Test")),
        ])

        actor ProgressCollector {
            var events: [ImportProgress] = []
            func append(_ event: ImportProgress) { events.append(event) }
        }
        let collector = ProgressCollector()

        let progressHandler: BackupImporter.ProgressHandler = { event in
            Task { await collector.append(event) }
        }

        let result = await importer.importBackup(from: zipURL, progress: progressHandler)

        try await Task.sleep(nanoseconds: 100_000_000)
        let progressEvents = await collector.events

        // Basic validation
        XCTAssertFalse(progressEvents.isEmpty, "Should have at least one progress event")

        // First event should be openingArchive
        if case .openingArchive = progressEvents.first {
            // good
        } else {
            XCTFail("First progress event should be .openingArchive, got \(String(describing: progressEvents.first))")
        }

        // Last event should be completed
        if case .completed = progressEvents.last {
            // good
        } else {
            XCTFail("Last progress event should be .completed, got \(String(describing: progressEvents.last))")
        }

        // Should have extracting events
        let extractEvents = progressEvents.filter {
            if case .extractingEntries = $0 { return true }
            return false
        }
        XCTAssertFalse(extractEvents.isEmpty, "Should have extraction progress events")

        // Should have readingDatabase event
        let readingEvents = progressEvents.filter {
            if case .readingDatabase = $0 { return true }
            return false
        }
        XCTAssertFalse(readingEvents.isEmpty, "Should have readingDatabase progress event")

        // Should have completed with valid result
        if case .completed(let finalResult) = progressEvents.last {
            XCTAssertEqual(finalResult.importedFiles, result.importedFiles)
        }

        // Result should be valid
        XCTAssertEqual(result.importedFiles, 3, "1 loose + 2 DB songs")
    }

    func testImportSingleFileThroughAPI() async throws {
        let songData = makeOnSongContent(title: "Test Song", artist: "Artist", body: "Verse 1:\n[C]Test")
        let sourceURL = tmpDir.appendingPathComponent("test.onsong")
        try songData.write(to: sourceURL)

        let result = await importer.importSingleFile(from: sourceURL)

        XCTAssertTrue(result.success)
        XCTAssertEqual(result.message, "Imported successfully")

        let destURL = libraryRoot.appendingPathComponent("test.onsong")
        XCTAssertTrue(FileManager.default.fileExists(atPath: destURL.path))
    }

    // MARK: - End-to-End Backup Import

    func testEndToEndBackupImportThroughAPI() async throws {
        // Create a realistic backup with database
        let dbURL = tmpDir.appendingPathComponent("OnSong.sqlite3")
        try createOnSongTestDatabase(at: dbURL)

        let zipURL = tmpDir.appendingPathComponent("backup.zip")
        try createTestZip(at: zipURL, files: [
            ("OnSong.sqlite3", try Data(contentsOf: dbURL)),
            ("loose.onsong", makeOnSongContent(title: "Loose Song", body: "Verse 1:\n[C]Test")),
        ])

        let result = await importer.importBackup(from: zipURL)

        // 1 loose file + 2 DB songs + 2 setlists
        XCTAssertGreaterThanOrEqual(result.totalFiles, 3)
        XCTAssertGreaterThanOrEqual(result.importedFiles, 3)
        XCTAssertEqual(result.errors.count, 0)

        // Verify files on disk
        let amazingURL = libraryRoot.appendingPathComponent("Amazing Grace-G.onsong")
        let howGreatURL = libraryRoot.appendingPathComponent("How Great Thou Art-C.onsong")
        let looseURL = libraryRoot.appendingPathComponent("loose.onsong")

        XCTAssertTrue(FileManager.default.fileExists(atPath: amazingURL.path), "Amazing Grace should be imported")
        XCTAssertTrue(FileManager.default.fileExists(atPath: howGreatURL.path), "How Great Thou Art should be imported")
        XCTAssertTrue(FileManager.default.fileExists(atPath: looseURL.path), "Loose song should be imported")

        // Verify content is structured FreeSong format (not raw OnSong)
        let amazingContent = try String(contentsOf: amazingURL, encoding: .utf8)
        XCTAssertTrue(amazingContent.contains("{title:"), "Should be structured FreeSong format")
        XCTAssertTrue(amazingContent.contains("Amazing Grace"), "Title should be present")

        let looseContent = try String(contentsOf: looseURL, encoding: .utf8)
        XCTAssertTrue(looseContent.contains("Loose Song") || looseContent.contains("{title:"),
                      "Content should be readable")
    }
}

import XCTest
@testable import FreeSongCore

final class AccidentalConverterTests: XCTestCase {

    // MARK: - Convert to Flats

    func testConvertToFlatsBasic() {
        let result = AccidentalConverter.convertToFlats("C# D# F# G# A#")
        XCTAssertEqual(result, "Db Eb Gb Ab Bb")
    }

    func testConvertToFlatsInlineChords() {
        let result = AccidentalConverter.convertToFlats("[C#m]Amazing [F#]grace")
        XCTAssertEqual(result, "[Dbm]Amazing [Gb]grace")
    }

    func testConvertToFlatsChordsAbove() {
        let input = "C#       F#\nAmazing grace"
        let result = AccidentalConverter.convertToFlats(input)
        XCTAssertEqual(result, "Db       Gb\nAmazing grace")
    }

    func testConvertToFlatsSlashChords() {
        let result = AccidentalConverter.convertToFlats("G/B C#/G#")
        XCTAssertEqual(result, "G/B Db/Ab")
    }

    // MARK: - Convert to Sharps

    func testConvertToSharpsBasic() {
        let result = AccidentalConverter.convertToSharps("Db Eb Gb Ab Bb")
        XCTAssertEqual(result, "C# D# F# G# A#")
    }

    func testConvertToSharpsInlineChords() {
        let result = AccidentalConverter.convertToSharps("[Dbm]Amazing [Gb]grace")
        XCTAssertEqual(result, "[C#m]Amazing [F#]grace")
    }

    func testConvertToSharpsChordsAbove() {
        let input = "Db       Gb\nAmazing grace"
        let result = AccidentalConverter.convertToSharps(input)
        XCTAssertEqual(result, "C#       F#\nAmazing grace")
    }

    func testConvertToSharpsSlashChords() {
        let result = AccidentalConverter.convertToSharps("G/B Db/Ab")
        XCTAssertEqual(result, "G/B C#/G#")
    }

    // MARK: - Detection

    func testIsSharpsFormat() {
        XCTAssertTrue(AccidentalConverter.isSharpsFormat("C# D# F#"))
        XCTAssertTrue(AccidentalConverter.isSharpsFormat("[C#m] [F#]"))
        XCTAssertTrue(AccidentalConverter.isSharpsFormat("C D E")) // no accidentals -> sharps
    }

    func testIsFlatsFormat() {
        XCTAssertFalse(AccidentalConverter.isSharpsFormat("Db Eb Gb"))
        XCTAssertFalse(AccidentalConverter.isSharpsFormat("[Dbm] [Gb]"))
    }

    func testEqualSharpsFlats() {
        // When equal, defaults to sharps
        XCTAssertTrue(AccidentalConverter.isSharpsFormat("C# Db"))
    }

    // MARK: - Edge Cases

    func testEmptyString() {
        XCTAssertEqual(AccidentalConverter.convertToFlats(""), "")
        XCTAssertEqual(AccidentalConverter.convertToSharps(""), "")
    }

    func testNoAccidentals() {
        XCTAssertEqual(AccidentalConverter.convertToFlats("C D E"), "C D E")
        XCTAssertEqual(AccidentalConverter.convertToSharps("C D E"), "C D E")
    }

    func testMixedContent() {
        let input = "Verse 1:\n[C#m]Amazing [F#]grace\nDb       Gb\nHow sweet the sound"
        let toFlats = AccidentalConverter.convertToFlats(input)
        XCTAssertTrue(toFlats.contains("[Dbm]"))
        XCTAssertTrue(toFlats.contains("[Gb]"))
        XCTAssertTrue(toFlats.contains("Db       Gb"))
    }

    func testUnicodeAccidentals() {
        // Unicode sharp/flat should be handled
        let result = AccidentalConverter.convertToFlats("C♯ D♯")
        XCTAssertEqual(result, "Db Eb")

        let result2 = AccidentalConverter.convertToSharps("D♭ E♭")
        XCTAssertEqual(result2, "C# D#")
    }
}

