import Foundation
import FreeSongCore

// MARK: - JSON Metadata Cache

/// File-based metadata cache using JSON.
/// Replaces the Android SQLite cache with a simpler, faster JSON file.
public actor JSONMetadataCache: MetadataCache {

    private let cacheFile: URL
    private var cache: [String: CachedMetadataEntry] = [:]
    /// Debounces disk writes: a burst of `cacheMetadata` calls (e.g. parsing
    /// a whole library on first launch) previously rewrote the whole JSON file
    /// on every single call, making cold start O(N^2) in file I/O. Now only
    /// the last call in a burst actually saves.
    private var pendingSave: Task<Void, Never>?

    public init() {
        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
        let freeSongDir = appSupport.appendingPathComponent("FreeSong", isDirectory: true)
        self.init(cacheFile: freeSongDir.appendingPathComponent("metadata.json"))
    }

    /// Testable initializer pointing at an arbitrary cache file location.
    init(cacheFile: URL) {
        try? FileManager.default.createDirectory(at: cacheFile.deletingLastPathComponent(), withIntermediateDirectories: true)
        self.cacheFile = cacheFile

        // Load cache synchronously during init (safe because init runs before any concurrent access)
        if FileManager.default.fileExists(atPath: cacheFile.path) {
            if let data = try? Data(contentsOf: cacheFile),
               let decoded = try? JSONDecoder().decode([String: CachedMetadataEntry].self, from: data) {
                cache = decoded
            } else {
                // Corrupt cache — delete so next launch starts fresh
                try? FileManager.default.removeItem(at: cacheFile)
            }
        }
    }

    public func getCachedMetadata(for file: URL) async -> CachedMetadata? {
        let path = file.path
        if let entry = cache[path] {
            let fileModified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? Date.distantPast
            if entry.lastModified == fileModified {
                return CachedMetadata(title: entry.title, artist: entry.artist, lastModified: entry.lastModified)
            }
        }
        return nil
    }

    public func cacheMetadata(for file: URL, title: String, artist: String?) async {
        let path = file.path
        let fileModified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? Date()

        let entry = CachedMetadataEntry(
            title: title,
            artist: artist,
            lastModified: fileModified
        )

        cache[path] = entry
        scheduleSave()
    }

    public func removeStaleEntries(validPaths: Set<String>) async {
        cache = cache.filter { validPaths.contains($0.key) }
        scheduleSave()
    }

    public var cacheSize: Int {
        cache.count
    }

    // MARK: - Private

    private struct CachedMetadataEntry: Codable {
        let title: String
        let artist: String?
        let lastModified: Date
    }

    /// Write-behind: coalesce a burst of mutations into a single disk write
    /// ~50ms after the last one, instead of writing on every call.
    /// ponytail: fixed short delay, not a full write-behind queue with a
    /// flush-on-terminate hook — if the process is killed inside that window
    /// the last few entries just get re-parsed next launch (cache miss, not
    /// data loss, since the source of truth is the song files on disk).
    private func scheduleSave() {
        pendingSave?.cancel()
        pendingSave = Task { [weak self] in
            try? await Task.sleep(nanoseconds: 50_000_000)
            guard !Task.isCancelled else { return }
            await self?.saveCache()
        }
    }

    private func saveCache() {
        guard let data = try? JSONEncoder().encode(cache) else { return }
        try? data.write(to: cacheFile, options: .atomic)
    }
}

package org.freesong;

import android.util.Base64;
import android.util.Log;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.ArrayList;
import java.util.List;

/**
 * GitHub REST API client for file operations.
 * Uses HttpURLConnection for Android 4.4 compatibility.
 */
public class GitHubApiClient {

    private static final String TAG = "GitHubApiClient";
    private static final String API_BASE = "https://api.github.com";
    private static final int TIMEOUT_MS = 30000;

    private String token;
    private String repo;
    private String lastError;  // Stores last error for debugging

    /**
     * Represents a file in a GitHub repository.
     */
    public static class GitHubFile {
        public String name;
        public String path;
        public String sha;
        public long size;
        public String type;  // "file" or "dir"
        public String downloadUrl;

        @Override
        public String toString() {
            return "GitHubFile{name='" + name + "', path='" + path + "', sha='" + sha + "'}";
        }
    }

    /**
     * API response wrapper.
     */
    public static class ApiResponse {
        public boolean success;
        public int statusCode;
        public String body;
        public String errorMessage;

        public ApiResponse(boolean success, int statusCode, String body, String errorMessage) {
            this.success = success;
            this.statusCode = statusCode;
            this.body = body;
            this.errorMessage = errorMessage;
        }
    }

    public GitHubApiClient(String token, String repo) {
        this.token = token;
        this.repo = repo;
        this.lastError = null;
    }

    /**
     * Get the last error message (for debugging).
     */
    public String getLastError() {
        return lastError;
    }

    /**
     * Test the connection and credentials.
     * @return true if connection successful, false otherwise
     */
    public ApiResponse testConnection() {
        try {
            ApiResponse response = doRequest("GET", "/repos/" + repo, null);
            if (response.success) {
                JSONObject json = new JSONObject(response.body);
                String repoName = json.getString("full_name");
                Log.d(TAG, "Connected to repository: " + repoName);
            }
            return response;
        } catch (Exception e) {
            Log.e(TAG, "Connection test failed", e);
            return new ApiResponse(false, -1, null, e.getMessage());
        }
    }

    /**
     * List files in a directory.
     * @param path Directory path (empty string for root)
     * @return List of files, or empty list on error
     */
    public List<GitHubFile> listFiles(String path) {
        List<GitHubFile> files = new ArrayList<GitHubFile>();

        try {
            String endpoint = "/repos/" + repo + "/contents/" + path;
            ApiResponse response = doRequest("GET", endpoint, null);

            if (!response.success) {
                Log.e(TAG, "Failed to list files: " + response.errorMessage);
                return files;
            }

            JSONArray array = new JSONArray(response.body);
            for (int i = 0; i < array.length(); i++) {
                JSONObject obj = array.getJSONObject(i);
                GitHubFile file = new GitHubFile();
                file.name = obj.getString("name");
                file.path = obj.getString("path");
                file.sha = obj.getString("sha");
                file.size = obj.optLong("size", 0);
                file.type = obj.getString("type");
                file.downloadUrl = obj.optString("download_url", null);
                files.add(file);
            }
        } catch (JSONException e) {
            Log.e(TAG, "JSON parse error listing files", e);
        }

        return files;
    }

    /**
     * Get a single file's metadata (including SHA).
     * @param path File path
     * @return GitHubFile or null if not found
     */
    public GitHubFile getFile(String path) {
        try {
            String endpoint = "/repos/" + repo + "/contents/" + path;
            ApiResponse response = doRequest("GET", endpoint, null);

            if (!response.success) {
                if (response.statusCode == 404) {
                    return null;  // File doesn't exist
                }
                Log.e(TAG, "Failed to get file: " + response.errorMessage);
                return null;
            }

            JSONObject obj = new JSONObject(response.body);
            GitHubFile file = new GitHubFile();
            file.name = obj.getString("name");
            file.path = obj.getString("path");
            file.sha = obj.getString("sha");
            file.size = obj.optLong("size", 0);
            file.type = obj.getString("type");
            file.downloadUrl = obj.optString("download_url", null);
            return file;
        } catch (JSONException e) {
            Log.e(TAG, "JSON parse error getting file", e);
            return null;
        }
    }

    /**
     * Get file content as string.
     * @param path File path
     * @return File content or null on error
     */
    public String getFileContent(String path) {
        try {
            String endpoint = "/repos/" + repo + "/contents/" + path;
            ApiResponse response = doRequest("GET", endpoint, null);

            if (!response.success) {
                Log.e(TAG, "Failed to get file content: " + response.errorMessage);
                return null;
            }

            JSONObject obj = new JSONObject(response.body);
            String encoding = obj.optString("encoding", "base64");
            String content = obj.getString("content");

            if ("base64".equals(encoding)) {
                // Remove newlines that GitHub adds to base64
                content = content.replace("\n", "");
                byte[] decoded = Base64.decode(content, Base64.DEFAULT);
                return new String(decoded, "UTF-8");
            } else {
                return content;
            }
        } catch (Exception e) {
            Log.e(TAG, "Error getting file content", e);
            return null;
        }
    }

    /**
     * Create or update a file.
     * @param path File path
     * @param content File content
     * @param sha Existing SHA (null for new file)
     * @param message Commit message
     * @return ApiResponse
     */
    public ApiResponse createOrUpdateFile(String path, String content, String sha, String message) {
        try {
            String endpoint = "/repos/" + repo + "/contents/" + path;

            JSONObject body = new JSONObject();
            body.put("message", message);
            body.put("content", encodeBase64(content));
            if (sha != null && !sha.isEmpty()) {
                body.put("sha", sha);
            }

            return doRequest("PUT", endpoint, body.toString());
        } catch (JSONException e) {
            Log.e(TAG, "Error creating request body", e);
            return new ApiResponse(false, -1, null, e.getMessage());
        }
    }

    /**
     * Delete a file.
     * @param path File path
     * @param sha File SHA (required)
     * @param message Commit message
     * @return ApiResponse
     */
    public ApiResponse deleteFile(String path, String sha, String message) {
        try {
            String endpoint = "/repos/" + repo + "/contents/" + path;

            JSONObject body = new JSONObject();
            body.put("message", message);
            body.put("sha", sha);

            return doRequest("DELETE", endpoint, body.toString());
        } catch (JSONException e) {
            Log.e(TAG, "Error creating request body", e);
            return new ApiResponse(false, -1, null, e.getMessage());
        }
    }

    /**
     * Ensure a directory exists by creating a .gitkeep file if needed.
     * @param dirPath Directory path
     * @return true if directory exists or was created
     */
    public boolean ensureDirectory(String dirPath) {
        List<GitHubFile> files = listFiles(dirPath);
        if (!files.isEmpty()) {
            return true;  // Directory exists with files
        }

        // Try to create a .gitkeep file to create the directory
        String gitkeepPath = dirPath + "/.gitkeep";
        ApiResponse response = createOrUpdateFile(gitkeepPath, "", null, "Create directory");
        return response.success;
    }

    /**
     * Perform an HTTP request to the GitHub API.
     */
    private ApiResponse doRequest(String method, String endpoint, String body) {
        HttpURLConnection conn = null;
        try {
            URL url = new URL(API_BASE + endpoint);
            conn = (HttpURLConnection) url.openConnection();

            // Android 4.4 HttpURLConnection doesn't support PATCH properly
            // Use POST with X-HTTP-Method-Override header as workaround
            if ("PATCH".equals(method)) {
                conn.setRequestMethod("POST");
                conn.setRequestProperty("X-HTTP-Method-Override", "PATCH");
                Log.d(TAG, "Using X-HTTP-Method-Override for PATCH request");
            } else {
                conn.setRequestMethod(method);
            }

            conn.setConnectTimeout(TIMEOUT_MS);
            conn.setReadTimeout(TIMEOUT_MS);

            // Headers
            conn.setRequestProperty("Authorization", "token " + token);
            conn.setRequestProperty("Accept", "application/vnd.github.v3+json");
            conn.setRequestProperty("User-Agent", "FreeSong-Android");

            // Body for PUT/POST/DELETE
            if (body != null && !body.isEmpty()) {
                conn.setRequestProperty("Content-Type", "application/json");
                conn.setDoOutput(true);
                OutputStream os = conn.getOutputStream();
                os.write(body.getBytes("UTF-8"));
                os.close();
            }

            int statusCode = conn.getResponseCode();
            boolean success = statusCode >= 200 && statusCode < 300;

            // Read response
            BufferedReader reader;
            if (success) {
                reader = new BufferedReader(new InputStreamReader(conn.getInputStream(), "UTF-8"));
            } else {
                reader = new BufferedReader(new InputStreamReader(conn.getErrorStream(), "UTF-8"));
            }

            StringBuilder responseBody = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                responseBody.append(line);
            }
            reader.close();

            String errorMessage = null;
            if (!success) {
                try {
                    JSONObject errorJson = new JSONObject(responseBody.toString());
                    errorMessage = errorJson.optString("message", "HTTP " + statusCode);
                } catch (JSONException e) {
                    errorMessage = "HTTP " + statusCode;
                }
            }

            return new ApiResponse(success, statusCode, responseBody.toString(), errorMessage);

        } catch (IOException e) {
            Log.e(TAG, "HTTP request failed: " + method + " " + endpoint, e);
            return new ApiResponse(false, -1, null, e.getMessage());
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    /**
     * Encode content to Base64.
     */
    private String encodeBase64(String content) {
        try {
            byte[] bytes = content.getBytes("UTF-8");
            return Base64.encodeToString(bytes, Base64.NO_WRAP);
        } catch (Exception e) {
            return "";
        }
    }

    // ==================== Git Trees API (Batch Operations) ====================

    /**
     * File entry for batch upload.
     */
    public static class TreeEntry {
        public String path;
        public String content;

        public TreeEntry(String path, String content) {
            this.path = path;
            this.content = content;
        }
    }

    /**
     * Get the SHA of the latest commit on a branch.
     * @param branch Branch name (e.g., "main" or "master")
     * @return SHA string or null on error
     */
    public String getLatestCommitSha(String branch) {
        try {
            String endpoint = "/repos/" + repo + "/git/refs/heads/" + branch;
            ApiResponse response = doRequest("GET", endpoint, null);

            if (!response.success) {
                lastError = "Get branch ref failed: HTTP " + response.statusCode + " - " + response.errorMessage;
                Log.e(TAG, lastError);
                return null;
            }

            JSONObject json = new JSONObject(response.body);
            return json.getJSONObject("object").getString("sha");
        } catch (Exception e) {
            lastError = "Get commit SHA exception: " + e.getMessage();
            Log.e(TAG, lastError, e);
            return null;
        }
    }

    /**
     * Get the tree SHA from a commit.
     * @param commitSha Commit SHA
     * @return Tree SHA or null on error
     */
    public String getTreeSha(String commitSha) {
        try {
            String endpoint = "/repos/" + repo + "/git/commits/" + commitSha;
            ApiResponse response = doRequest("GET", endpoint, null);

            if (!response.success) {
                lastError = "Get tree SHA failed: HTTP " + response.statusCode + " - " + response.errorMessage;
                Log.e(TAG, lastError);
                return null;
            }

            JSONObject json = new JSONObject(response.body);
            return json.getJSONObject("tree").getString("sha");
        } catch (Exception e) {
            lastError = "Get tree SHA exception: " + e.getMessage();
            Log.e(TAG, lastError, e);
            return null;
        }
    }

    /**
     * Create a blob for a file and return its SHA.
     * This is needed for larger files (>100KB) or to avoid request size limits.
     * @param content File content
     * @return Blob SHA or null on error
     */
    public String createBlob(String content) {
        try {
            JSONObject body = new JSONObject();
            body.put("content", encodeBase64(content));
            body.put("encoding", "base64");

            String endpoint = "/repos/" + repo + "/git/blobs";
            ApiResponse response = doRequest("POST", endpoint, body.toString());

            if (!response.success) {
                lastError = "Blob creation failed: HTTP " + response.statusCode + " - " + response.errorMessage;
                Log.e(TAG, lastError);
                return null;
            }

            JSONObject json = new JSONObject(response.body);
            return json.getString("sha");
        } catch (Exception e) {
            lastError = "Blob exception: " + e.getMessage();
            Log.e(TAG, lastError, e);
            return null;
        }
    }

    /**
     * Create a new tree with multiple files (batch upload).
     * Creates blobs first for each file, then references them by SHA.
     * @param baseTreeSha Base tree SHA (can be null for new repo)
     * @param entries List of files to add/update
     * @return New tree SHA or null on error
     */
    public String createTree(String baseTreeSha, List<TreeEntry> entries) {
        try {
            // First, create blobs for all files
            Log.d(TAG, "Creating blobs for " + entries.size() + " files...");
            List<String> blobShas = new ArrayList<String>();
            int blobCount = 0;
            for (TreeEntry entry : entries) {
                String blobSha = createBlob(entry.content);
                if (blobSha == null) {
                    Log.e(TAG, "Failed to create blob for: " + entry.path);
                    return null;
                }
                blobShas.add(blobSha);
                blobCount++;
                if (blobCount % 10 == 0) {
                    Log.d(TAG, "Created " + blobCount + "/" + entries.size() + " blobs...");
                }
            }
            Log.d(TAG, "All " + blobCount + " blobs created successfully");

            // Now create tree with blob references
            JSONObject body = new JSONObject();

            if (baseTreeSha != null && !baseTreeSha.isEmpty()) {
                body.put("base_tree", baseTreeSha);
            }

            JSONArray tree = new JSONArray();
            for (int i = 0; i < entries.size(); i++) {
                TreeEntry entry = entries.get(i);
                String blobSha = blobShas.get(i);

                JSONObject item = new JSONObject();
                item.put("path", entry.path);
                item.put("mode", "100644");  // Regular file
                item.put("type", "blob");
                item.put("sha", blobSha);  // Reference blob by SHA instead of inline content
                tree.put(item);
            }
            body.put("tree", tree);

            String endpoint = "/repos/" + repo + "/git/trees";
            ApiResponse response = doRequest("POST", endpoint, body.toString());

            if (!response.success) {
                lastError = "Create tree failed: HTTP " + response.statusCode + " - " + response.errorMessage;
                Log.e(TAG, lastError);
                return null;
            }

            JSONObject json = new JSONObject(response.body);
            return json.getString("sha");
        } catch (Exception e) {
            lastError = "Create tree exception: " + e.getMessage();
            Log.e(TAG, lastError, e);
            return null;
        }
    }

    /**
     * Create a new commit.
     * @param message Commit message
     * @param treeSha Tree SHA
     * @param parentSha Parent commit SHA
     * @return New commit SHA or null on error
     */
    public String createCommit(String message, String treeSha, String parentSha) {
        try {
            JSONObject body = new JSONObject();
            body.put("message", message);
            body.put("tree", treeSha);

            JSONArray parents = new JSONArray();
            if (parentSha != null && !parentSha.isEmpty()) {
                parents.put(parentSha);
            }
            body.put("parents", parents);

            String endpoint = "/repos/" + repo + "/git/commits";
            ApiResponse response = doRequest("POST", endpoint, body.toString());

            if (!response.success) {
                lastError = "Create commit failed: HTTP " + response.statusCode + " - " + response.errorMessage;
                Log.e(TAG, lastError);
                return null;
            }

            JSONObject json = new JSONObject(response.body);
            return json.getString("sha");
        } catch (Exception e) {
            lastError = "Create commit exception: " + e.getMessage();
            Log.e(TAG, lastError, e);
            return null;
        }
    }

    /**
     * Update a branch reference to point to a new commit.
     * @param branch Branch name
     * @param commitSha New commit SHA
     * @return true on success
     */
    public boolean updateRef(String branch, String commitSha) {
        try {
            JSONObject body = new JSONObject();
            body.put("sha", commitSha);
            body.put("force", false);

            String endpoint = "/repos/" + repo + "/git/refs/heads/" + branch;
            ApiResponse response = doRequest("PATCH", endpoint, body.toString());

            if (!response.success) {
                lastError = "Update ref failed: HTTP " + response.statusCode + " - " + response.errorMessage;
                Log.e(TAG, lastError);
                return false;
            }

            return true;
        } catch (Exception e) {
            lastError = "Update ref exception: " + e.getMessage();
            Log.e(TAG, lastError, e);
            return false;
        }
    }

    /**
     * Upload multiple files in a single commit (batch upload).
     * @param branch Branch name (e.g., "main")
     * @param entries Files to upload
     * @param message Commit message
     * @return true on success
     */
    public boolean batchUpload(String branch, List<TreeEntry> entries, String message) {
        lastError = null;  // Clear previous error

        if (entries == null || entries.isEmpty()) {
            return true;  // Nothing to upload
        }

        Log.d(TAG, "Batch uploading " + entries.size() + " files to branch '" + branch + "'...");

        // 1. Get latest commit SHA
        Log.d(TAG, "Step 1: Getting latest commit SHA...");
        String commitSha = getLatestCommitSha(branch);
        if (commitSha == null) {
            Log.e(TAG, "FAILED: Could not get latest commit for branch: " + branch);
            return false;
        }
        Log.d(TAG, "Got commit SHA: " + commitSha.substring(0, 7));

        // 2. Get base tree SHA
        Log.d(TAG, "Step 2: Getting base tree SHA...");
        String baseTreeSha = getTreeSha(commitSha);
        if (baseTreeSha == null) {
            Log.e(TAG, "FAILED: Could not get base tree");
            return false;
        }
        Log.d(TAG, "Got tree SHA: " + baseTreeSha.substring(0, 7));

        // 3. Create new tree with all files
        Log.d(TAG, "Step 3: Creating tree with " + entries.size() + " files...");
        String newTreeSha = createTree(baseTreeSha, entries);
        if (newTreeSha == null) {
            Log.e(TAG, "FAILED: Could not create tree (API limit exceeded?)");
            return false;
        }
        Log.d(TAG, "Created tree SHA: " + newTreeSha.substring(0, 7));

        // 4. Create commit
        Log.d(TAG, "Step 4: Creating commit...");
        String newCommitSha = createCommit(message, newTreeSha, commitSha);
        if (newCommitSha == null) {
            Log.e(TAG, "FAILED: Could not create commit");
            return false;
        }
        Log.d(TAG, "Created commit SHA: " + newCommitSha.substring(0, 7));

        // 5. Update branch reference
        Log.d(TAG, "Step 5: Updating branch reference...");
        boolean success = updateRef(branch, newCommitSha);
        if (success) {
            Log.d(TAG, "SUCCESS: Batch upload complete - " + entries.size() + " files in 1 commit");
        } else {
            Log.e(TAG, "FAILED: Could not update branch reference");
        }

        return success;
    }

    /**
     * Detect the default branch of the repository.
     * @return Branch name ("main" or "master") or null on error
     */
    public String getDefaultBranch() {
        try {
            ApiResponse response = doRequest("GET", "/repos/" + repo, null);
            if (!response.success) {
                return null;
            }

            JSONObject json = new JSONObject(response.body);
            return json.optString("default_branch", "main");
        } catch (Exception e) {
            Log.e(TAG, "Error getting default branch", e);
            return "main";
        }
    }
}

package org.freesong;

import android.app.Activity;
import android.app.AlertDialog;
import android.app.ProgressDialog;
import android.content.DialogInterface;
import android.content.Intent;
import android.os.AsyncTask;
import android.os.Bundle;
import android.os.Environment;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.AdapterView;
import android.widget.BaseAdapter;
import android.widget.Button;
import android.widget.ListView;
import android.widget.TextView;
import android.widget.Toast;

import java.io.File;
import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Simple file browser for selecting backup files to import.
 */
public class FileBrowserActivity extends Activity {

    private ListView fileListView;
    private TextView pathText;
    private Button cancelBtn;
    private Button themeBtn;

    private File currentDir;
    private List<File> files = new ArrayList<File>();
    private FileAdapter adapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        ThemeManager.applyTheme(this);
        setContentView(R.layout.activity_file_browser);

        fileListView = (ListView) findViewById(R.id.fileListView);
        pathText = (TextView) findViewById(R.id.pathText);
        cancelBtn = (Button) findViewById(R.id.cancelBtn);
        themeBtn = (Button) findViewById(R.id.themeBtn);

        updateThemeButton();

        themeBtn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                toggleTheme();
            }
        });

        adapter = new FileAdapter();
        fileListView.setAdapter(adapter);

        fileListView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                File file = files.get(position);
                if (file.isDirectory()) {
                    navigateTo(file);
                } else {
                    selectFile(file);
                }
            }
        });

        cancelBtn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                setResult(RESULT_CANCELED);
                finish();
            }
        });

        // Start at external storage root
        currentDir = Environment.getExternalStorageDirectory();
        loadFiles();
    }

    private void toggleTheme() {
        ThemeManager.toggleDarkMode(this);
        recreate();
    }

    private void updateThemeButton() {
        if (ThemeManager.isDarkMode(this)) {
            themeBtn.setText(R.string.theme_icon_sun);
        } else {
            themeBtn.setText(R.string.theme_icon_moon);
        }
    }

    @Override
    public void onBackPressed() {
        if (currentDir != null && currentDir.getParentFile() != null) {
            File parent = currentDir.getParentFile();
            if (parent.canRead()) {
                navigateTo(parent);
                return;
            }
        }
        super.onBackPressed();
    }

    private void navigateTo(File dir) {
        if (dir.canRead()) {
            currentDir = dir;
            loadFiles();
        } else {
            Toast.makeText(this, "Cannot access this folder", Toast.LENGTH_SHORT).show();
        }
    }

    private void loadFiles() {
        files.clear();
        pathText.setText(currentDir.getAbsolutePath());

        // Add parent directory option if not at root
        File parent = currentDir.getParentFile();
        if (parent != null && parent.canRead()) {
            // We'll handle ".." specially in the adapter
        }

        File[] fileArray = currentDir.listFiles();
        if (fileArray != null) {
            for (File file : fileArray) {
                // Skip hidden files
                if (file.getName().startsWith(".")) {
                    continue;
                }
                // Show directories and importable files
                if (file.isDirectory() || isImportableFile(file)) {
                    files.add(file);
                }
            }
        }

        // Sort: directories first, then files, both alphabetically
        Collections.sort(files, new Comparator<File>() {
            @Override
            public int compare(File f1, File f2) {
                if (f1.isDirectory() && !f2.isDirectory()) {
                    return -1;
                } else if (!f1.isDirectory() && f2.isDirectory()) {
                    return 1;
                }
                return f1.getName().compareToIgnoreCase(f2.getName());
            }
        });

        // Add parent at top if available
        if (parent != null && parent.canRead()) {
            files.add(0, parent);
        }

        adapter.notifyDataSetChanged();
    }

    private boolean isImportableFile(File file) {
        String name = file.getName().toLowerCase();
        return BackupImporter.isBackupFile(name) ||
               name.endsWith(".onsong") ||
               name.endsWith(".chordpro") ||
               name.endsWith(".cho") ||
               name.endsWith(".crd") ||
               name.endsWith(".pro") ||
               name.endsWith(".txt");
    }

    private void selectFile(final File file) {
        String name = file.getName().toLowerCase();

        if (BackupImporter.isBackupFile(name)) {
            // It's a backup file - confirm and import
            new AlertDialog.Builder(this)
                .setTitle("Import Backup")
                .setMessage("Import songs from:\n" + file.getName() + "?")
                .setPositiveButton("Import", new DialogInterface.OnClickListener() {
                    @Override
                    public void onClick(DialogInterface dialog, int which) {
                        importBackupFile(file);
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
        } else {
            // It's a single song file
            new AlertDialog.Builder(this)
                .setTitle("Import Song")
                .setMessage("Import:\n" + file.getName() + "?")
                .setPositiveButton("Import", new DialogInterface.OnClickListener() {
                    @Override
                    public void onClick(DialogInterface dialog, int which) {
                        importSingleFile(file);
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
        }
    }

    private void importBackupFile(final File file) {
        final ProgressDialog progress = new ProgressDialog(this);
        progress.setMessage("Importing songs...\nThis may take a while for large backups.");
        progress.setCancelable(false);
        progress.setProgressStyle(ProgressDialog.STYLE_SPINNER);
        progress.show();

        // Keep screen on during import
        getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);

        new AsyncTask<Void, Void, BackupImporter.ImportResult>() {
            private Exception error;

            @Override
            protected BackupImporter.ImportResult doInBackground(Void... params) {
                try {
                    return BackupImporter.importBackup(file, FileBrowserActivity.this);
                } catch (Exception e) {
                    error = e;
                    return null;
                }
            }

            @Override
            protected void onPostExecute(BackupImporter.ImportResult result) {
                progress.dismiss();
                // Allow screen to turn off again
                getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);

                if (error != null) {
                    Toast.makeText(FileBrowserActivity.this,
                        "Import failed: " + error.getMessage(),
                        Toast.LENGTH_LONG).show();
                    return;
                }

                StringBuilder message = new StringBuilder();
                message.append("Songs imported: ").append(result.importedFiles).append("\n");
                if (result.skippedFiles > 0) {
                    message.append("Songs skipped: ").append(result.skippedFiles).append(" (already exist)\n");
                }
                if (result.skippedBinary > 0) {
                    message.append("Binary files skipped: ").append(result.skippedBinary).append("\n");
                }
                if (result.importedSetlists > 0) {
                    message.append("\nSetlists imported: ").append(result.importedSetlists).append("\n");
                }
                if (result.skippedSetlists > 0) {
                    message.append("Setlists skipped: ").append(result.skippedSetlists).append(" (already exist)\n");
                }
                if (!result.warnings.isEmpty()) {
                    message.append("\nWarnings:\n");
                    for (int i = 0; i < Math.min(result.warnings.size(), 5); i++) {
                        message.append("- ").append(result.warnings.get(i)).append("\n");
                    }
                    if (result.warnings.size() > 5) {
                        message.append("... and ").append(result.warnings.size() - 5).append(" more\n");
                    }
                }
                if (!result.errors.isEmpty()) {
                    message.append("\nErrors: ").append(result.errors.size());
                }

                new AlertDialog.Builder(FileBrowserActivity.this)
                    .setTitle("Import Complete")
                    .setMessage(message.toString())
                    .setPositiveButton("OK", new DialogInterface.OnClickListener() {
                        @Override
                        public void onClick(DialogInterface dialog, int which) {
                            setResult(RESULT_OK);
                            finish();
                        }
                    })
                    .show();
            }
        }.execute();
    }

    private void importSingleFile(File file) {
        try {
            BackupImporter.ImportSingleResult result = BackupImporter.importSingleFile(file);
            if (result.success) {
                Toast.makeText(this, "Imported: " + file.getName(), Toast.LENGTH_SHORT).show();
                setResult(RESULT_OK);
                finish();
            } else {
                Toast.makeText(this, result.message, Toast.LENGTH_SHORT).show();
            }
        } catch (Exception e) {
            Toast.makeText(this, "Import failed: " + e.getMessage(), Toast.LENGTH_SHORT).show();
        }
    }

    private class FileAdapter extends BaseAdapter {

        private DecimalFormat sizeFormat = new DecimalFormat("#.##");

        @Override
        public int getCount() {
            return files.size();
        }

        @Override
        public Object getItem(int position) {
            return files.get(position);
        }

        @Override
        public long getItemId(int position) {
            return position;
        }

        @Override
        public View getView(int position, View convertView, ViewGroup parent) {
            if (convertView == null) {
                convertView = LayoutInflater.from(FileBrowserActivity.this)
                    .inflate(R.layout.item_file, parent, false);
            }

            File file = files.get(position);
            boolean isParent = (position == 0 && file.equals(currentDir.getParentFile()));

            TextView iconText = (TextView) convertView.findViewById(R.id.fileIcon);
            TextView nameText = (TextView) convertView.findViewById(R.id.fileName);
            TextView infoText = (TextView) convertView.findViewById(R.id.fileInfo);

            if (isParent) {
                iconText.setText("⬆");
                nameText.setText("..");
                infoText.setVisibility(View.GONE);
            } else if (file.isDirectory()) {
                iconText.setText("📁");
                nameText.setText(file.getName());
                infoText.setVisibility(View.GONE);
            } else {
                String name = file.getName().toLowerCase();
                if (BackupImporter.isBackupFile(name)) {
                    iconText.setText("📦");
                } else {
                    iconText.setText("🎵");
                }
                nameText.setText(file.getName());
                infoText.setText(formatFileSize(file.length()));
                infoText.setVisibility(View.VISIBLE);
            }

            return convertView;
        }

        private String formatFileSize(long bytes) {
            if (bytes < 1024) {
                return bytes + " B";
            } else if (bytes < 1024 * 1024) {
                return sizeFormat.format(bytes / 1024.0) + " KB";
            } else {
                return sizeFormat.format(bytes / (1024.0 * 1024.0)) + " MB";
            }
        }
    }
}

package org.freesong;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Converts chord accidentals between sharp and flat notation.
 */
public class AccidentalConverter {

    // Enharmonic mappings: sharp -> flat
    private static final String[][] SHARP_TO_FLAT = {
        {"C#", "Db"},
        {"D#", "Eb"},
        {"F#", "Gb"},
        {"G#", "Ab"},
        {"A#", "Bb"}
    };

    /**
     * Convert all sharps to flats in the content.
     * Works on both inline [C#m] and chords-above C#m formats.
     */
    public static String convertToFlats(String content) {
        String result = content;

        // Handle inline chords [C#m] -> [Dbm]
        result = convertInlineChords(result, true);

        // Handle standalone chords (above format)
        result = convertStandaloneChords(result, true);

        return result;
    }

    /**
     * Convert all flats to sharps in the content.
     */
    public static String convertToSharps(String content) {
        String result = content;

        // Handle inline chords [Dbm] -> [C#m]
        result = convertInlineChords(result, false);

        // Handle standalone chords (above format)
        result = convertStandaloneChords(result, false);

        return result;
    }

    private static String convertInlineChords(String content, boolean toFlats) {
        StringBuffer sb = new StringBuffer();
        Matcher matcher = Pattern.compile("\\[([^\\]]+)\\]").matcher(content);

        while (matcher.find()) {
            String chord = matcher.group(1);
            String converted = convertChord(chord, toFlats);
            matcher.appendReplacement(sb, "[" + Matcher.quoteReplacement(converted) + "]");
        }
        matcher.appendTail(sb);
        return sb.toString();
    }

    private static String convertStandaloneChords(String content, boolean toFlats) {
        // Process line by line to only convert chord-only lines
        StringBuilder result = new StringBuilder();
        String[] lines = content.split("\n", -1);

        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (ChordFormatConverter.isChordOnlyLine(line)) {
                // Convert each chord on this line
                StringBuffer sb = new StringBuffer();
                Matcher matcher = Pattern.compile(
                    "([A-G][#b]?)(m|maj|min|dim|aug|sus|add|M)?(\\d+)?(sus|add)?(\\d+)?(/[A-G][#b]?)?"
                ).matcher(line);

                while (matcher.find()) {
                    String fullChord = matcher.group();
                    String converted = convertChord(fullChord, toFlats);
                    matcher.appendReplacement(sb, Matcher.quoteReplacement(converted));
                }
                matcher.appendTail(sb);
                result.append(sb.toString());
            } else {
                result.append(line);
            }
            if (i < lines.length - 1) {
                result.append("\n");
            }
        }
        return result.toString();
    }

    /**
     * Convert a single chord's accidentals.
     */
    private static String convertChord(String chord, boolean toFlats) {
        if (chord == null || chord.isEmpty()) return chord;

        // Handle slash chords (G/B, C#m/G#)
        int slashIndex = chord.indexOf('/');
        if (slashIndex > 0) {
            String mainPart = chord.substring(0, slashIndex);
            String bassPart = chord.substring(slashIndex + 1);
            return convertChord(mainPart, toFlats) + "/" + convertChord(bassPart, toFlats);
        }

        if (toFlats) {
            // Sharp to flat
            for (String[] pair : SHARP_TO_FLAT) {
                if (chord.startsWith(pair[0])) {
                    return pair[1] + chord.substring(pair[0].length());
                }
            }
        } else {
            // Flat to sharp
            for (String[] pair : SHARP_TO_FLAT) {
                if (chord.startsWith(pair[1])) {
                    return pair[0] + chord.substring(pair[1].length());
                }
            }
        }
        return chord;
    }

    /**
     * Detect if content predominantly uses sharps or flats.
     * @return true if predominantly sharps, false if flats
     */
    public static boolean isSharpsFormat(String content) {
        int sharpCount = 0;
        int flatCount = 0;

        Matcher matcher = Pattern.compile("[A-G]([#b])").matcher(content);
        while (matcher.find()) {
            if (matcher.group(1).equals("#")) {
                sharpCount++;
            } else {
                flatCount++;
            }
        }

        return sharpCount >= flatCount; // Default to sharps if equal or no accidentals
    }
}

package org.freesong;

import android.content.Context;
import android.os.Environment;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.util.List;

/**
 * Manages setlist backup and restore to/from JSON file.
 * Backup file is stored in FreeSong folder to survive app uninstallation.
 */
public class SetlistBackupManager {

    private static final String BACKUP_FILENAME = "setlists-backup.json";
    private static final String CHARSET = "UTF-8";

    /**
     * Get the backup file location.
     */
    public static File getBackupFile() {
        File freeSongDir = new File(Environment.getExternalStorageDirectory(), "FreeSong");
        if (!freeSongDir.exists()) {
            freeSongDir.mkdirs();
        }
        return new File(freeSongDir, BACKUP_FILENAME);
    }

    /**
     * Export all setlists to JSON backup file.
     * @return true if successful
     */
    public static boolean exportSetlists(Context context) {
        try {
            SetListDbHelper dbHelper = SetListDbHelper.getInstance(context);
            List<SetList> setlists = dbHelper.getAllSetLists();

            JSONObject backup = new JSONObject();
            backup.put("version", 1);
            backup.put("exported_at", System.currentTimeMillis());

            JSONArray setlistsArray = new JSONArray();
            for (SetList setlist : setlists) {
                JSONObject setlistObj = new JSONObject();
                setlistObj.put("name", setlist.getName());
                setlistObj.put("created_at", setlist.getCreatedAt());
                setlistObj.put("modified_at", setlist.getModifiedAt());

                JSONArray itemsArray = new JSONArray();
                for (SetList.SetListItem item : setlist.getItems()) {
                    JSONObject itemObj = new JSONObject();
                    itemObj.put("song_path", item.getSongPath());
                    itemObj.put("song_title", item.getSongTitle());
                    itemObj.put("song_artist", item.getSongArtist());
                    itemObj.put("position", item.getPosition());
                    itemObj.put("notes", item.getNotes());
                    itemsArray.put(itemObj);
                }
                setlistObj.put("items", itemsArray);
                setlistsArray.put(setlistObj);
            }
            backup.put("setlists", setlistsArray);

            // Write to file
            File backupFile = getBackupFile();
            BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(new FileOutputStream(backupFile), CHARSET));
            writer.write(backup.toString(2)); // Pretty print with indent
            writer.close();

            return true;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    /**
     * Import setlists from JSON backup file.
     * @param merge If true, merge with existing setlists. If false, only import non-existing.
     * @return Number of setlists imported, or -1 on error
     */
    public static int importSetlists(Context context, boolean merge) {
        try {
            File backupFile = getBackupFile();
            if (!backupFile.exists()) {
                return 0;
            }

            // Read file
            StringBuilder content = new StringBuilder();
            BufferedReader reader = new BufferedReader(
                new InputStreamReader(new FileInputStream(backupFile), CHARSET));
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
            }
            reader.close();

            JSONObject backup = new JSONObject(content.toString());
            JSONArray setlistsArray = backup.getJSONArray("setlists");

            SetListDbHelper dbHelper = SetListDbHelper.getInstance(context);
            List<SetList> existingSetlists = dbHelper.getAllSetLists();

            int imported = 0;
            for (int i = 0; i < setlistsArray.length(); i++) {
                JSONObject setlistObj = setlistsArray.getJSONObject(i);
                String name = setlistObj.getString("name");

                // Check if setlist already exists
                boolean exists = false;
                for (SetList existing : existingSetlists) {
                    if (existing.getName().equalsIgnoreCase(name)) {
                        exists = true;
                        break;
                    }
                }

                if (exists && !merge) {
                    continue; // Skip existing
                }

                if (exists) {
                    // Delete existing to replace with backup
                    for (SetList existing : existingSetlists) {
                        if (existing.getName().equalsIgnoreCase(name)) {
                            dbHelper.deleteSetList(existing.getId());
                            break;
                        }
                    }
                }

                // Create setlist
                SetList setlist = new SetList(name);
                if (setlistObj.has("created_at")) {
                    setlist.setCreatedAt(setlistObj.getLong("created_at"));
                }
                if (setlistObj.has("modified_at")) {
                    setlist.setModifiedAt(setlistObj.getLong("modified_at"));
                }

                long setlistId = dbHelper.createSetList(setlist);

                // Add items
                JSONArray itemsArray = setlistObj.getJSONArray("items");
                for (int j = 0; j < itemsArray.length(); j++) {
                    JSONObject itemObj = itemsArray.getJSONObject(j);
                    SetList.SetListItem item = new SetList.SetListItem(
                        itemObj.getString("song_path"),
                        itemObj.optString("song_title", ""),
                        itemObj.optString("song_artist", "")
                    );
                    if (itemObj.has("notes")) {
                        item.setNotes(itemObj.getString("notes"));
                    }
                    dbHelper.addItemToSetList(setlistId, item);
                }

                imported++;
            }

            return imported;
        } catch (Exception e) {
            e.printStackTrace();
            return -1;
        }
    }

    /**
     * Check if a backup file exists.
     */
    public static boolean backupExists() {
        return getBackupFile().exists();
    }

    /**
     * Get backup file info for display.
     */
    public static String getBackupInfo() {
        File backupFile = getBackupFile();
        if (!backupFile.exists()) {
            return null;
        }

        try {
            StringBuilder content = new StringBuilder();
            BufferedReader reader = new BufferedReader(
                new InputStreamReader(new FileInputStream(backupFile), CHARSET));
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
            }
            reader.close();

            JSONObject backup = new JSONObject(content.toString());
            int count = backup.getJSONArray("setlists").length();
            long exportedAt = backup.optLong("exported_at", 0);

            String date = "";
            if (exportedAt > 0) {
                java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm");
                date = sdf.format(new java.util.Date(exportedAt));
            }

            return count + " setlists (" + date + ")";
        } catch (Exception e) {
            return "Unknown";
        }
    }
}

package org.freesong;

import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Environment;

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.nio.charset.Charset;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Imports songs from OnSong backup files (.backup, .zip).
 */
public class BackupImporter {

    private static final int BUFFER_SIZE = 4096;

    public static class ImportResult {
        public int totalFiles = 0;
        public int importedFiles = 0;
        public int skippedFiles = 0;
        public int skippedBinary = 0;
        public int importedSetlists = 0;
        public int skippedSetlists = 0;
        public List<String> importedNames = new ArrayList<String>();
        public List<String> importedSetlistNames = new ArrayList<String>();
        public List<String> warnings = new ArrayList<String>();
        public List<String> errors = new ArrayList<String>();
    }

    public static class ImportSingleResult {
        public boolean success = false;
        public String message = "";
    }

    /**
     * Import songs from a backup file (ZIP format).
     * Supports both loose song files and OnSong SQLite database.
     */
    public static ImportResult importBackup(File backupFile) throws IOException {
        return importBackup(backupFile, null);
    }

    /**
     * Import songs and optionally setlists from a backup file.
     * @param backupFile The backup file to import
     * @param context Context for setlist import (pass null to skip setlist import)
     */
    public static ImportResult importBackup(File backupFile, Context context) throws IOException {
        ImportResult result = new ImportResult();

        File destDir = new File(Environment.getExternalStorageDirectory(), "FreeSong");
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Temporary file for SQLite database extraction
        File tempDbFile = null;

        ZipInputStream zis = null;
        try {
            zis = new ZipInputStream(new BufferedInputStream(new FileInputStream(backupFile)));
            ZipEntry entry;

            while ((entry = zis.getNextEntry()) != null) {
                String name = entry.getName();

                // Skip directories
                if (entry.isDirectory()) {
                    continue;
                }

                // Check for OnSong SQLite database
                if (name.equals("OnSong.sqlite3") || name.endsWith("/OnSong.sqlite3")) {
                    tempDbFile = new File(destDir, ".onsong_temp.sqlite3");
                    extractBinaryFile(zis, tempDbFile);
                    zis.closeEntry();
                    continue;
                }

                // Check if it's a song file
                String lowerName = name.toLowerCase();
                if (!isSongFile(lowerName)) {
                    continue;
                }

                result.totalFiles++;

                // Extract just the filename (remove path)
                String fileName = name;
                int lastSlash = name.lastIndexOf('/');
                if (lastSlash >= 0) {
                    fileName = name.substring(lastSlash + 1);
                }

                // Skip hidden files
                if (fileName.startsWith(".")) {
                    result.skippedFiles++;
                    continue;
                }

                File destFile = new File(destDir, fileName);

                // Skip if file already exists
                if (destFile.exists()) {
                    result.skippedFiles++;
                    continue;
                }

                try {
                    extractFile(zis, destFile, result);
                    // Check if file was actually created (not skipped binary)
                    if (destFile.exists()) {
                        result.importedFiles++;
                        result.importedNames.add(getDisplayName(fileName));
                    }
                } catch (IOException e) {
                    result.errors.add(fileName + ": " + e.getMessage());
                }

                zis.closeEntry();
            }
        } finally {
            if (zis != null) {
                try {
                    zis.close();
                } catch (IOException e) {
                    // Ignore
                }
            }
        }

        // Import songs from SQLite database if found
        if (tempDbFile != null && tempDbFile.exists()) {
            try {
                importFromSqliteDatabase(tempDbFile, destDir, result);
                // Import setlists if context provided
                if (context != null) {
                    importSetlistsFromDatabase(tempDbFile, destDir, context, result);
                }
            } catch (Exception e) {
                result.errors.add("Database import: " + e.getMessage());
            } finally {
                // Clean up temporary database file
                tempDbFile.delete();
            }
        }

        return result;
    }

    /**
     * Import songs from OnSong SQLite database.
     */
    private static void importFromSqliteDatabase(File dbFile, File destDir, ImportResult result) {
        SQLiteDatabase db = null;
        Cursor cursor = null;
        try {
            db = SQLiteDatabase.openDatabase(dbFile.getAbsolutePath(), null, SQLiteDatabase.OPEN_READONLY);

            // Query songs with content
            cursor = db.rawQuery(
                "SELECT title, byline, key, content FROM Song WHERE content IS NOT NULL AND content != ''",
                null
            );

            while (cursor.moveToNext()) {
                String title = cursor.getString(0);
                String artist = cursor.getString(1);
                String key = cursor.getString(2);
                String content = cursor.getString(3);

                // Skip if no title or content
                if (title == null || title.trim().isEmpty() ||
                    content == null || content.trim().isEmpty()) {
                    continue;
                }

                result.totalFiles++;

                // Create safe filename from title
                String safeTitle = sanitizeFileName(title);
                if (safeTitle.isEmpty()) {
                    safeTitle = "Untitled_" + System.currentTimeMillis();
                }

                // Add key to filename if available
                String fileName = safeTitle;
                if (key != null && !key.trim().isEmpty()) {
                    fileName = safeTitle + "-" + key.trim();
                }
                fileName = fileName + ".onsong";

                File destFile = new File(destDir, fileName);

                // Skip if file already exists
                if (destFile.exists()) {
                    result.skippedFiles++;
                    continue;
                }

                try {
                    // Write song content to file
                    writeSongFile(destFile, content);
                    result.importedFiles++;
                    result.importedNames.add(title);
                } catch (IOException e) {
                    result.errors.add(title + ": " + e.getMessage());
                }
            }
        } catch (Exception e) {
            result.errors.add("Failed to read database: " + e.getMessage());
        } finally {
            if (cursor != null) {
                cursor.close();
            }
            if (db != null) {
                db.close();
            }
        }
    }

    /**
     * Create a safe filename from song title.
     */
    private static String sanitizeFileName(String name) {
        if (name == null) return "";
        // Remove or replace invalid filename characters
        String safe = name.replaceAll("[\\\\/:*?\"<>|]", "_");
        // Remove leading/trailing spaces and dots
        safe = safe.trim();
        while (safe.endsWith(".")) {
            safe = safe.substring(0, safe.length() - 1);
        }
        // Limit length
        if (safe.length() > 100) {
            safe = safe.substring(0, 100);
        }
        return safe;
    }

    /**
     * Write song content to file as UTF-8.
     */
    private static void writeSongFile(File destFile, String content) throws IOException {
        BufferedWriter writer = null;
        try {
            writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(destFile), UTF8));
            writer.write(content);
            writer.flush();
        } finally {
            if (writer != null) {
                writer.close();
            }
        }
    }

    /**
     * Import setlists from OnSong SQLite database.
     */
    private static void importSetlistsFromDatabase(File dbFile, File songsDir, Context context, ImportResult result) {
        SQLiteDatabase db = null;
        Cursor setlistCursor = null;
        try {
            db = SQLiteDatabase.openDatabase(dbFile.getAbsolutePath(), null, SQLiteDatabase.OPEN_READONLY);
            SetListDbHelper dbHelper = SetListDbHelper.getInstance(context);

            // Get existing setlist names to avoid duplicates
            List<SetList> existingSetlists = dbHelper.getAllSetLists();
            List<String> existingNames = new ArrayList<String>();
            for (SetList sl : existingSetlists) {
                existingNames.add(sl.getName().toLowerCase());
            }

            // Query all setlists
            setlistCursor = db.rawQuery(
                "SELECT ID, title FROM SongSet WHERE title IS NOT NULL AND title != '' ORDER BY title",
                null
            );

            while (setlistCursor.moveToNext()) {
                String setlistId = setlistCursor.getString(0);
                String setlistTitle = setlistCursor.getString(1);

                if (setlistTitle == null || setlistTitle.trim().isEmpty()) {
                    continue;
                }

                // Skip if setlist already exists
                if (existingNames.contains(setlistTitle.toLowerCase().trim())) {
                    result.skippedSetlists++;
                    continue;
                }

                // Get songs in this setlist
                Cursor itemsCursor = null;
                try {
                    itemsCursor = db.rawQuery(
                        "SELECT s.title, s.key, s.byline FROM SongSetItem ssi " +
                        "JOIN Song s ON ssi.songID = s.ID " +
                        "WHERE ssi.setID = ? ORDER BY ssi.orderIndex",
                        new String[]{setlistId}
                    );

                    if (itemsCursor.getCount() == 0) {
                        continue; // Empty setlist
                    }

                    // Create the setlist
                    SetList newSetList = new SetList(setlistTitle.trim());
                    long newSetlistId = dbHelper.createSetList(newSetList);
                    int songsAdded = 0;

                    while (itemsCursor.moveToNext()) {
                        String songTitle = itemsCursor.getString(0);
                        String songKey = itemsCursor.getString(1);
                        String songArtist = itemsCursor.getString(2);

                        if (songTitle == null || songTitle.trim().isEmpty()) {
                            continue;
                        }

                        // Try to find matching song file
                        File songFile = findSongFile(songsDir, songTitle, songKey);
                        if (songFile != null) {
                            SetList.SetListItem item = new SetList.SetListItem(
                                songFile.getAbsolutePath(),
                                songTitle,
                                songArtist != null ? songArtist : ""
                            );
                            dbHelper.addItemToSetList(newSetlistId, item);
                            songsAdded++;
                        }
                    }

                    if (songsAdded > 0) {
                        result.importedSetlists++;
                        result.importedSetlistNames.add(setlistTitle + " (" + songsAdded + " songs)");
                    } else {
                        // Remove empty setlist
                        dbHelper.deleteSetList(newSetlistId);
                    }

                } finally {
                    if (itemsCursor != null) {
                        itemsCursor.close();
                    }
                }
            }
        } catch (Exception e) {
            result.errors.add("Setlist import: " + e.getMessage());
        } finally {
            if (setlistCursor != null) {
                setlistCursor.close();
            }
            if (db != null) {
                db.close();
            }
        }
    }

    /**
     * Find a song file by title and optional key.
     */
    private static File findSongFile(File songsDir, String title, String key) {
        if (!songsDir.exists()) return null;

        String safeTitle = sanitizeFileName(title);

        // Try different filename patterns
        String[] patterns;
        if (key != null && !key.trim().isEmpty()) {
            patterns = new String[]{
                safeTitle + "-" + key.trim() + ".onsong",
                safeTitle + ".onsong",
                safeTitle + "-" + key.trim() + ".txt",
                safeTitle + ".txt",
                safeTitle + ".chordpro",
                safeTitle + ".cho"
            };
        } else {
            patterns = new String[]{
                safeTitle + ".onsong",
                safeTitle + ".txt",
                safeTitle + ".chordpro",
                safeTitle + ".cho"
            };
        }

        for (String pattern : patterns) {
            File file = new File(songsDir, pattern);
            if (file.exists()) {
                return file;
            }
        }

        // Try case-insensitive search
        File[] files = songsDir.listFiles();
        if (files != null) {
            String lowerTitle = safeTitle.toLowerCase();
            for (File file : files) {
                String name = file.getName().toLowerCase();
                if (name.startsWith(lowerTitle) && isSongFile(name)) {
                    return file;
                }
            }
        }

        return null;
    }

    /**
     * Import a single song file by copying it to FreeSong folder.
     */
    public static ImportSingleResult importSingleFile(File sourceFile) throws IOException {
        ImportSingleResult result = new ImportSingleResult();

        if (!isSongFile(sourceFile.getName().toLowerCase())) {
            result.success = false;
            result.message = "Not a song file";
            return result;
        }

        // Check for binary content
        byte[] header = new byte[1024];
        FileInputStream fis = null;
        try {
            fis = new FileInputStream(sourceFile);
            int read = fis.read(header);
            if (read > 0) {
                byte[] checkBytes = read < header.length ? java.util.Arrays.copyOf(header, read) : header;
                String binaryType = detectBinaryContent(checkBytes);
                if (binaryType != null) {
                    result.success = false;
                    result.message = "Cannot import " + binaryType;
                    return result;
                }
            }
        } finally {
            if (fis != null) {
                try { fis.close(); } catch (IOException e) { }
            }
        }

        File destDir = new File(Environment.getExternalStorageDirectory(), "FreeSong");
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        File destFile = new File(destDir, sourceFile.getName());
        if (destFile.exists()) {
            result.success = false;
            result.message = "File already exists";
            return result;
        }

        copyFile(sourceFile, destFile);
        result.success = true;
        result.message = "Imported successfully";
        return result;
    }

    private static boolean isSongFile(String lowerName) {
        return lowerName.endsWith(".onsong") ||
               lowerName.endsWith(".chordpro") ||
               lowerName.endsWith(".cho") ||
               lowerName.endsWith(".crd") ||
               lowerName.endsWith(".pro") ||
               lowerName.endsWith(".txt");
    }

    // Mac Roman charset for OnSong files
    private static final Charset MAC_ROMAN = Charset.forName("x-MacRoman");
    private static final Charset UTF8 = Charset.forName("UTF-8");

    /**
     * Check if content appears to be binary (PDF, image, etc).
     * Returns a description of detected binary type, or null if text.
     */
    private static String detectBinaryContent(byte[] content) {
        if (content == null || content.length < 8) {
            return null;
        }

        // PDF: starts with %PDF
        if (content[0] == '%' && content[1] == 'P' &&
            content[2] == 'D' && content[3] == 'F') {
            return "PDF document";
        }

        // PNG: starts with 0x89 PNG
        if ((content[0] & 0xFF) == 0x89 && content[1] == 'P' &&
            content[2] == 'N' && content[3] == 'G') {
            return "PNG image";
        }

        // JPEG: starts with 0xFF 0xD8 0xFF
        if ((content[0] & 0xFF) == 0xFF && (content[1] & 0xFF) == 0xD8 &&
            (content[2] & 0xFF) == 0xFF) {
            return "JPEG image";
        }

        // GIF: starts with GIF87a or GIF89a
        if (content[0] == 'G' && content[1] == 'I' && content[2] == 'F' &&
            content[3] == '8' && (content[4] == '7' || content[4] == '9')) {
            return "GIF image";
        }

        // BMP: starts with BM
        if (content[0] == 'B' && content[1] == 'M') {
            return "BMP image";
        }

        // Check for high proportion of non-printable characters (binary indicator)
        int nonPrintable = 0;
        int checkLength = Math.min(content.length, 1024);
        for (int i = 0; i < checkLength; i++) {
            byte b = content[i];
            // Allow printable ASCII, tabs, newlines, and high UTF-8 bytes
            if (b != 0x09 && b != 0x0A && b != 0x0D &&
                (b < 0x20 || b == 0x7F) && b >= 0) {
                nonPrintable++;
            }
        }

        // If more than 10% non-printable in first 1KB, likely binary
        if (nonPrintable > checkLength / 10) {
            return "binary file";
        }

        return null; // Appears to be text
    }

    private static void extractFile(ZipInputStream zis, File destFile, ImportResult result) throws IOException {
        // For text files, convert from Mac Roman to UTF-8
        String name = destFile.getName().toLowerCase();
        if (name.endsWith(".txt") || name.endsWith(".onsong") ||
            name.endsWith(".chordpro") || name.endsWith(".cho") ||
            name.endsWith(".crd") || name.endsWith(".pro")) {
            extractTextFile(zis, destFile, result);
        } else {
            extractBinaryFile(zis, destFile);
        }
    }

    private static void extractTextFile(ZipInputStream zis, File destFile, ImportResult result) throws IOException {
        // First, read raw bytes to check for binary content
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        byte[] buffer = new byte[BUFFER_SIZE];
        int count;
        while ((count = zis.read(buffer, 0, BUFFER_SIZE)) != -1) {
            baos.write(buffer, 0, count);
        }
        byte[] rawBytes = baos.toByteArray();

        // Check for binary content
        String binaryType = detectBinaryContent(rawBytes);
        if (binaryType != null) {
            result.skippedBinary++;
            result.warnings.add(destFile.getName() + ": Skipped (" + binaryType + ")");
            return;
        }

        // Convert from Mac Roman to UTF-8 and write
        BufferedWriter writer = null;
        try {
            String content = new String(rawBytes, MAC_ROMAN);
            writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(destFile), UTF8));
            writer.write(content);
            writer.flush();
        } finally {
            if (writer != null) {
                writer.close();
            }
        }
    }

    private static void extractBinaryFile(ZipInputStream zis, File destFile) throws IOException {
        BufferedOutputStream bos = null;
        try {
            bos = new BufferedOutputStream(new FileOutputStream(destFile), BUFFER_SIZE);
            byte[] buffer = new byte[BUFFER_SIZE];
            int count;
            while ((count = zis.read(buffer, 0, BUFFER_SIZE)) != -1) {
                bos.write(buffer, 0, count);
            }
            bos.flush();
        } finally {
            if (bos != null) {
                bos.close();
            }
        }
    }

    private static void copyFile(File source, File dest) throws IOException {
        InputStream is = null;
        BufferedOutputStream bos = null;
        try {
            is = new BufferedInputStream(new FileInputStream(source));
            bos = new BufferedOutputStream(new FileOutputStream(dest), BUFFER_SIZE);
            byte[] buffer = new byte[BUFFER_SIZE];
            int count;
            while ((count = is.read(buffer)) != -1) {
                bos.write(buffer, 0, count);
            }
            bos.flush();
        } finally {
            if (is != null) {
                try { is.close(); } catch (IOException e) { }
            }
            if (bos != null) {
                try { bos.close(); } catch (IOException e) { }
            }
        }
    }

    private static String getDisplayName(String fileName) {
        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex > 0) {
            return fileName.substring(0, dotIndex);
        }
        return fileName;
    }

    /**
     * Check if a file looks like an OnSong backup.
     */
    public static boolean isBackupFile(String fileName) {
        String lower = fileName.toLowerCase();
        return lower.endsWith(".backup") ||
               lower.endsWith(".zip") ||
               lower.endsWith(".onsong-backup");
    }
}

package org.freesong;

import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;

import java.io.File;
import java.util.HashSet;
import java.util.Set;

/**
 * SQLite cache for song metadata (title, artist).
 * Speeds up app startup by avoiding re-parsing unchanged song files.
 */
public class SongMetadataCache extends SQLiteOpenHelper {

    private static final String DB_NAME = "song_metadata.db";
    private static final int DB_VERSION = 1;

    private static final String TABLE_NAME = "metadata";
    private static final String COL_PATH = "path";
    private static final String COL_TITLE = "title";
    private static final String COL_ARTIST = "artist";
    private static final String COL_LAST_MODIFIED = "last_modified";

    private static SongMetadataCache instance;

    public static synchronized SongMetadataCache getInstance(Context context) {
        if (instance == null) {
            instance = new SongMetadataCache(context.getApplicationContext());
        }
        return instance;
    }

    private SongMetadataCache(Context context) {
        super(context, DB_NAME, null, DB_VERSION);
    }

    @Override
    public void onCreate(SQLiteDatabase db) {
        db.execSQL("CREATE TABLE " + TABLE_NAME + " (" +
            COL_PATH + " TEXT PRIMARY KEY, " +
            COL_TITLE + " TEXT, " +
            COL_ARTIST + " TEXT, " +
            COL_LAST_MODIFIED + " INTEGER)");
    }

    @Override
    public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
        db.execSQL("DROP TABLE IF EXISTS " + TABLE_NAME);
        onCreate(db);
    }

    /**
     * Result of a cache lookup.
     */
    public static class CachedMetadata {
        public final String title;
        public final String artist;
        public final long lastModified;

        public CachedMetadata(String title, String artist, long lastModified) {
            this.title = title;
            this.artist = artist;
            this.lastModified = lastModified;
        }
    }

    /**
     * Get cached metadata for a file.
     * Returns null if not cached or if file has been modified since caching.
     */
    public CachedMetadata getCached(File file) {
        String path = file.getAbsolutePath();
        long fileModified = file.lastModified();

        SQLiteDatabase db = getReadableDatabase();
        Cursor cursor = db.query(TABLE_NAME,
            new String[]{COL_TITLE, COL_ARTIST, COL_LAST_MODIFIED},
            COL_PATH + " = ?",
            new String[]{path},
            null, null, null);

        try {
            if (cursor.moveToFirst()) {
                long cachedModified = cursor.getLong(2);
                // Only return cached data if file hasn't changed
                if (cachedModified == fileModified) {
                    return new CachedMetadata(
                        cursor.getString(0),
                        cursor.getString(1),
                        cachedModified
                    );
                }
            }
        } finally {
            cursor.close();
        }

        return null;
    }

    /**
     * Cache metadata for a file.
     */
    public void cache(File file, String title, String artist) {
        String path = file.getAbsolutePath();
        long lastModified = file.lastModified();

        ContentValues values = new ContentValues();
        values.put(COL_PATH, path);
        values.put(COL_TITLE, title);
        values.put(COL_ARTIST, artist);
        values.put(COL_LAST_MODIFIED, lastModified);

        SQLiteDatabase db = getWritableDatabase();
        db.insertWithOnConflict(TABLE_NAME, null, values, SQLiteDatabase.CONFLICT_REPLACE);
    }

    /**
     * Remove stale cache entries for files that no longer exist.
     */
    public void removeStaleEntries(Set<String> validPaths) {
        SQLiteDatabase db = getWritableDatabase();
        Cursor cursor = db.query(TABLE_NAME, new String[]{COL_PATH}, null, null, null, null, null);

        Set<String> toDelete = new HashSet<String>();
        try {
            while (cursor.moveToNext()) {
                String path = cursor.getString(0);
                if (!validPaths.contains(path)) {
                    toDelete.add(path);
                }
            }
        } finally {
            cursor.close();
        }

        for (String path : toDelete) {
            db.delete(TABLE_NAME, COL_PATH + " = ?", new String[]{path});
        }
    }

    /**
     * Get the number of cached entries.
     */
    public int getCacheSize() {
        SQLiteDatabase db = getReadableDatabase();
        Cursor cursor = db.rawQuery("SELECT COUNT(*) FROM " + TABLE_NAME, null);
        try {
            if (cursor.moveToFirst()) {
                return cursor.getInt(0);
            }
        } finally {
            cursor.close();
        }
        return 0;
    }
}

import Foundation

// MARK: - HTTP Client Protocol

/// Abstract HTTP client for testability.
public protocol HTTPClient: Sendable {
    /// Send a request and return the raw response data and status code.
    func send(_ request: URLRequest) async throws -> (data: Data, statusCode: Int)
}

/// Production HTTP client using URLSession.
public struct URLSessionHTTPClient: HTTPClient {
    private let session: URLSession

    public init(session: URLSession = .shared) {
        self.session = session
    }

    public func send(_ request: URLRequest) async throws -> (data: Data, statusCode: Int) {
        let (data, response) = try await session.data(for: request)
        guard let httpResponse = response as? HTTPURLResponse else {
            throw SyncError.invalidResponse
        }
        return (data, httpResponse.statusCode)
    }
}

// MARK: - Codeberg API Client

/// Low-level REST client for the Codeberg (Gitea) Contents API.
///
/// Uses a Personal Access Token for authentication.
/// All file operations target a single branch in a single repository.
public actor CodebergAPIClient {

    private let configuration: CodebergConfiguration
    private let httpClient: HTTPClient

    // MARK: Initialization

    public init(
        configuration: CodebergConfiguration,
        httpClient: HTTPClient = URLSessionHTTPClient()
    ) {
        self.configuration = configuration
        self.httpClient = httpClient
    }

    // MARK: - Public API

    /// Fetch the SHA of the branch HEAD reference.
    public func getReference() async throws -> String {
        let url = url(for: "/repos/\(configuration.owner)/\(configuration.repo)/git/refs/heads/\(configuration.branch)")
        let request = try authenticatedRequest(url: url)
        let (data, statusCode) = try await httpClient.send(request)

        guard statusCode == 200 else {
            try throwMappedError(statusCode: statusCode, data: data)
            throw SyncError.networkError("Failed to get reference (HTTP \(statusCode))")
        }

        let ref = try JSONDecoder().decode(CodebergRef.self, from: data)
        return ref.object.sha
    }

    /// List all items at a given path in the repository.
    /// - Parameter path: Path relative to repo root (e.g. "songs").
    /// - Returns: Array of content items (files and directories).
    public func listDirectory(path: String) async throws -> [CodebergContentItem] {
        let encodedPath = path.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? path
        let url = url(for: "/repos/\(configuration.owner)/\(configuration.repo)/contents/\(encodedPath)")
        var components = URLComponents(url: url, resolvingAgainstBaseURL: false)
        components?.queryItems = [URLQueryItem(name: "ref", value: configuration.branch)]
        guard let finalURL = components?.url else {
            throw SyncError.networkError("Invalid URL for path: \(path)")
        }

        let request = try authenticatedRequest(url: finalURL)
        let (data, statusCode) = try await httpClient.send(request)

        switch statusCode {
        case 200:
            let decoder = JSONDecoder()
            decoder.keyDecodingStrategy = .convertFromSnakeCase
            return try decoder.decode([CodebergContentItem].self, from: data)
        case 404:
            return [] // Path doesn't exist yet
        default:
            try throwMappedError(statusCode: statusCode, data: data)
            throw SyncError.networkError("Failed to list directory (HTTP \(statusCode))")
        }
    }

    /// Get a single file's content and metadata.
    /// - Parameter path: Path to the file.
    /// - Returns: Tuple of decoded content + SHA for conflict detection.
    public func getFileContent(path: String) async throws -> (data: Data, sha: String) {
        let encodedPath = path.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? path
        let url = url(for: "/repos/\(configuration.owner)/\(configuration.repo)/contents/\(encodedPath)")
        var components = URLComponents(url: url, resolvingAgainstBaseURL: false)
        components?.queryItems = [URLQueryItem(name: "ref", value: configuration.branch)]
        guard let finalURL = components?.url else {
            throw SyncError.networkError("Invalid URL for path: \(path)")
        }

        let request = try authenticatedRequest(url: finalURL)
        let (data, statusCode) = try await httpClient.send(request)

        guard statusCode == 200 else {
            try throwMappedError(statusCode: statusCode, data: data)
            throw SyncError.networkError("Failed to get file content (HTTP \(statusCode))")
        }

        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        let item = try decoder.decode(CodebergContentItem.self, from: data)

        guard let base64Content = item.content,
              let decodedData = Data(base64Encoded: base64Content.trimmingCharacters(in: .whitespacesAndNewlines)) else {
            throw SyncError.networkError("Failed to decode file content from base64")
        }

        return (decodedData, item.sha)
    }

    /// Create or update a file at the given path.
    /// - Parameters:
    ///   - path: Path where the file should be stored.
    ///   - content: Raw data to write.
    ///   - sha: Existing file SHA (required for updates, nil for new files).
    /// - Returns: API response with commit SHA.
    /// - Throws: `SyncError.conflict` if the remote file has changed since last fetch.
    public func createOrUpdateFile(
        path: String,
        content: Data,
        sha: String?
    ) async throws -> CodebergCreateUpdateResponse {
        let encodedPath = path.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? path
        let url = url(for: "/repos/\(configuration.owner)/\(configuration.repo)/contents/\(encodedPath)")

        let body = CodebergCreateUpdateRequest(
            message: "Update \(path)",
            content: content.base64EncodedString(),
            sha: sha,
            branch: configuration.branch
        )

        var request = try authenticatedRequest(url: url)
        request.httpMethod = "PUT"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = try JSONEncoder().encode(body)

        let (data, statusCode) = try await httpClient.send(request)

        switch statusCode {
        case 200, 201:
            let decoder = JSONDecoder()
            decoder.keyDecodingStrategy = .convertFromSnakeCase
            return try decoder.decode(CodebergCreateUpdateResponse.self, from: data)
        case 409:
            throw SyncError.conflict("Remote file has changed. Fetch latest before updating.")
        default:
            try throwMappedError(statusCode: statusCode, data: data)
            throw SyncError.networkError("Failed to write file (HTTP \(statusCode))")
        }
    }

    /// Delete a file from the repository.
    public func deleteFile(path: String, sha: String) async throws {
        let encodedPath = path.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? path
        let url = url(for: "/repos/\(configuration.owner)/\(configuration.repo)/contents/\(encodedPath)")

        let body: [String: Any] = [
            "message": "Delete \(path)",
            "sha": sha,
            "branch": configuration.branch,
        ]
        let bodyData = try JSONSerialization.data(withJSONObject: body)

        var request = try authenticatedRequest(url: url)
        request.httpMethod = "DELETE"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = bodyData

        let (_, statusCode) = try await httpClient.send(request)

        guard statusCode == 200 else {
            throw SyncError.networkError("Failed to delete file (HTTP \(statusCode))")
        }
    }

    /// Validate that the configuration and token work by fetching the user's info.
    public func validateAccess() async throws -> Bool {
        let url = url(for: "/user")
        let request = try authenticatedRequest(url: url)
        let (_, statusCode) = try await httpClient.send(request)
        return statusCode == 200
    }

    // MARK: - Private Helpers

    private func url(for path: String) -> URL {
        guard let url = URL(string: configuration.baseURL + path) else {
            fatalError("Invalid URL: \(configuration.baseURL)\(path)")
        }
        return url
    }

    private func authenticatedRequest(url: URL) throws -> URLRequest {
        guard let token = try KeychainStorage.retrieve() else {
            throw SyncError.notAuthenticated
        }

        var request = URLRequest(url: url)
        request.setValue("token \(token)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        request.timeoutInterval = 30
        return request
    }

    /// Parse error response body from Codeberg API into a SyncError.
    private func throwMappedError(statusCode: Int, data: Data) throws {
        switch statusCode {
        case 401:
            throw SyncError.authenticationFailed("Token is invalid or expired")
        case 403:
            throw SyncError.authenticationFailed("Insufficient permissions")
        case 404:
            throw SyncError.notFound("Repository or path not found")
        case 409:
            throw SyncError.conflict("File conflict detected")
        default:
            if let errorBody = try? JSONDecoder().decode(CodebergErrorMessage.self, from: data) {
                throw SyncError.networkError(errorBody.message)
            }
        }
    }
}

// MARK: - Internal API Types

/// Response from the Git references endpoint.
struct CodebergRef: Codable {
    let ref: String
    let object: CodebergRefObject
    let url: String
}

struct CodebergRefObject: Codable {
    let sha: String
    let type: String
    let url: String
}

/// Error response body from Codeberg API.
struct CodebergErrorMessage: Codable {
    let message: String
    let documentationURL: String?

    enum CodingKeys: String, CodingKey {
        case message
        case documentationURL = "documentation_url"
    }
}

