// MARK: - KeyChange

/// Represents a key change within a song.
/// Used to transpose subsequent chords to a new key.
public struct KeyChange: Codable, Equatable, Hashable, Sendable {
    public var newKey: String

    public init(newKey: String) {
        self.newKey = newKey
    }
}

import Foundation

// MARK: - SongSection

/// Represents a section of a song (Verse, Chorus, Bridge, etc.)
public struct SongSection: Codable, Equatable, Hashable, Sendable {
    public var label: String
    public var lines: [SongLine]

    public init(label: String = "", lines: [SongLine] = []) {
        self.label = label
        self.lines = lines
    }

    public mutating func addLine(_ line: SongLine) {
        lines.append(line)
    }
}
